INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$3150021d$SATQ$, $SATQ$489d0e8e-1669-4e1e-9164-ea2f62fbead7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The Royal Alc&aacute;zar of Seville is a historic royal palace in Andaluc&iacute;a, Spain.</li>
<li>The palace is famous for its intricate tilework.</li>
<li>The palace features majolica and arista tiles.</li>
<li>In the majolica style, designs are painted directly on the ceramic tiles.</li>
<li>In the arista style, designs are stamped into the ceramic tiles.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to contrast the two styles of tiles. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"89f862b9-1696-4ab0-84f7-f1bebd4a8c42","content":"<p>Tiles in the majolica and arista styles can be found in the Royal Alc&aacute;zar of Seville in Andaluc&iacute;a, Spain.</p>"},{"id":"64626aa7-ddae-460a-b24d-83b3c3e6378f","content":"<p>Featuring tiles in the majolica and arista styles, the Royal Alc&aacute;zar of Seville in Spain is famous for its intricate tilework.</p>"},{"id":"b7e3a5ce-ba96-4e94-99e4-b33d4253130a","content":"<p>In the arista style, designs are stamped into the ceramic tiles, whereas in the majolica style, the designs are painted directly on them.</p>"},{"id":"7d55db0c-8d97-4f51-8256-481384a978ae","content":"<p>Among the famous tilework of the Royal Alc&aacute;zar of Seville are majolica style tiles, made by painting designs directly on the ceramic tiles.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b7e3a5ce-ba96-4e94-99e4-b33d4253130a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence contrasts the two styles of tiles, noting that tiles in the arista style have designs stamped into them, whereas tiles in the majolica style have designs painted directly on them.</p><p>Choice A is incorrect because the sentence indicates that the two styles of tile can be found in the same location; it doesn&rsquo;t contrast the two styles of tile. Choice B is incorrect because the sentence indicates that the Royal Alc&aacute;zar of Seville features tiles in both the majolica and arista styles; it doesn&rsquo;t contrast the two styles of tile. Choice D is incorrect because the sentence indicates that the tilework of the Royal Alc&aacute;zar of Seville includes tiles in the majolica style; it doesn&rsquo;t contrast tiles in the majolica style with tiles in the arista style.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3150021d","external_id":"489d0e8e-1669-4e1e-9164-ea2f62fbead7","vaultid":null,"uId":"f3ae5e69-82ae-42d7-85ed-0f5a17011d7b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The Royal Alc&aacute;zar of Seville is a historic royal palace in Andaluc&iacute;a, Spain.</li>\n<li>The palace is famous for its intricate tilework.</li>\n<li>The palace features majolica and arista tiles.</li>\n<li>In the majolica style, designs are painted directly on the ceramic tiles.</li>\n<li>In the arista style, designs are stamped into the ceramic tiles.</li>\n</ul>","stem":"<p>The student wants to contrast the two styles of tiles. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"89f862b9-1696-4ab0-84f7-f1bebd4a8c42","content":"<p>Tiles in the majolica and arista styles can be found in the Royal Alc&aacute;zar of Seville in Andaluc&iacute;a, Spain.</p>"},{"id":"64626aa7-ddae-460a-b24d-83b3c3e6378f","content":"<p>Featuring tiles in the majolica and arista styles, the Royal Alc&aacute;zar of Seville in Spain is famous for its intricate tilework.</p>"},{"id":"b7e3a5ce-ba96-4e94-99e4-b33d4253130a","content":"<p>In the arista style, designs are stamped into the ceramic tiles, whereas in the majolica style, the designs are painted directly on them.</p>"},{"id":"7d55db0c-8d97-4f51-8256-481384a978ae","content":"<p>Among the famous tilework of the Royal Alc&aacute;zar of Seville are majolica style tiles, made by painting designs directly on the ceramic tiles.</p>"}],"keys":["b7e3a5ce-ba96-4e94-99e4-b33d4253130a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence contrasts the two styles of tiles, noting that tiles in the arista style have designs stamped into them, whereas tiles in the majolica style have designs painted directly on them.</p><p>Choice A is incorrect because the sentence indicates that the two styles of tile can be found in the same location; it doesn&rsquo;t contrast the two styles of tile. Choice B is incorrect because the sentence indicates that the Royal Alc&aacute;zar of Seville features tiles in both the majolica and arista styles; it doesn&rsquo;t contrast the two styles of tile. Choice D is incorrect because the sentence indicates that the tilework of the Royal Alc&aacute;zar of Seville includes tiles in the majolica style; it doesn&rsquo;t contrast tiles in the majolica style with tiles in the arista style.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669206,"updateDate":1743430669206}$SATQ$::jsonb, 1743430669206, 1743430669206),
    ($SATQ$31ac4d2c$SATQ$, $SATQ$e2f7c1f1-940b-4949-92d5-fb17fa14b93a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Hina Hanta is an online archive curated by the Choctaw Nation of Oklahoma.</li>
<li>Hina Hanta means &ldquo;bright path&rdquo; in Choctaw.</li>
<li>It features images of cultural artifacts relevant to the history of the Choctaw people.</li>
<li>It includes a fanner basket (<span lang="cho"><em>ufko tapushik</em></span> in Choctaw) made from cane.</li>
<li>It includes a robe (<span lang="cho"><em>nita anchi</em></span>) made from bear fur.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to specify the fanner basket&rsquo;s name in Choctaw. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"782c248e-c5e0-4fcc-ada2-c04f0fb57be7","content":"<p>The Hina Hanta archive features cultural artifacts, such as a fanner basket and a robe, that are relevant to the history of the Choctaw people.</p>"},{"id":"2be9c100-e980-47b2-bca9-53d7f0603c06","content":"<p>The cane fanner basket, which is included in the Hina Hanta online archive, is called an <span lang=\"cho\"><em>ufko tapushik</em></span>&nbsp;in Choctaw.</p>"},{"id":"69c46c50-8031-4e93-9ddc-7f8a01679030","content":"<p>Hina Hanta, which means &ldquo;bright path&rdquo; in Choctaw, includes a fanner basket in its archive.</p>"},{"id":"a3aae71f-ed06-4ef1-9446-9489e06d111d","content":"<p>The name of the online archive Hina Hanta means &ldquo;bright path&rdquo; in Choctaw.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["2be9c100-e980-47b2-bca9-53d7f0603c06"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence specifies the fanner basket&rsquo;s name in Choctaw, noting that it&rsquo;s called <span lang="cho"><em>ufko tapushik</em></span>.</p><p>Choice A is incorrect. While the sentence mentions the fanner basket, it doesn&rsquo;t specify its name in Choctaw. Choice C is incorrect. While the sentence mentions the fanner basket, it doesn&rsquo;t specify its name in Choctaw. Choice D is incorrect. The sentence doesn&rsquo;t mention the fanner basket or specify its name in Choctaw.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"31ac4d2c","external_id":"e2f7c1f1-940b-4949-92d5-fb17fa14b93a","vaultid":null,"uId":"42b1a64e-33e3-4fd0-8bcd-6cacb4e77bcb","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Hina Hanta is an online archive curated by the Choctaw Nation of Oklahoma.</li>\n<li>Hina Hanta means &ldquo;bright path&rdquo; in Choctaw.</li>\n<li>It features images of cultural artifacts relevant to the history of the Choctaw people.</li>\n<li>It includes a fanner basket (<span lang=\"cho\"><em>ufko tapushik</em></span> in Choctaw) made from cane.</li>\n<li>It includes a robe (<span lang=\"cho\"><em>nita anchi</em></span>) made from bear fur.</li>\n</ul>","stem":"<p>The student wants to specify the fanner basket&rsquo;s name in Choctaw. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"782c248e-c5e0-4fcc-ada2-c04f0fb57be7","content":"<p>The Hina Hanta archive features cultural artifacts, such as a fanner basket and a robe, that are relevant to the history of the Choctaw people.</p>"},{"id":"2be9c100-e980-47b2-bca9-53d7f0603c06","content":"<p>The cane fanner basket, which is included in the Hina Hanta online archive, is called an <span lang=\"cho\"><em>ufko tapushik</em></span>&nbsp;in Choctaw.</p>"},{"id":"69c46c50-8031-4e93-9ddc-7f8a01679030","content":"<p>Hina Hanta, which means &ldquo;bright path&rdquo; in Choctaw, includes a fanner basket in its archive.</p>"},{"id":"a3aae71f-ed06-4ef1-9446-9489e06d111d","content":"<p>The name of the online archive Hina Hanta means &ldquo;bright path&rdquo; in Choctaw.</p>"}],"keys":["2be9c100-e980-47b2-bca9-53d7f0603c06"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence specifies the fanner basket&rsquo;s name in Choctaw, noting that it&rsquo;s called <span lang=\"cho\"><em>ufko tapushik</em></span>.</p><p>Choice A is incorrect. While the sentence mentions the fanner basket, it doesn&rsquo;t specify its name in Choctaw. Choice C is incorrect. While the sentence mentions the fanner basket, it doesn&rsquo;t specify its name in Choctaw. Choice D is incorrect. The sentence doesn&rsquo;t mention the fanner basket or specify its name in Choctaw.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061192,"updateDate":1755117061192}$SATQ$::jsonb, 1755117061192, 1755117061192),
    ($SATQ$326017ce$SATQ$, $SATQ$db7f27c9-80b1-4168-9dda-b415c1979457$SATQ$::uuid, $SATQ$cbff438f-ec3a-4703-9875-3b829508861e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>For years, biologists have experimented with using grime-eating bacteria rather than harsh chemicals to clean artworks, and results have been impressive overall. <span aria-hidden="true">______</span><span class="sr-only">blank</span> these bacterial strains&mdash;which can metabolize centuries&rsquo; worth of oil, glue, dirt, and other surface impurities without creating harmful byproducts&mdash;have proven more effective than traditional chemical cleaning methods.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"6c713a0f-0b50-4f17-947c-1b3557524bd2","content":"<p>However,</p>"},{"id":"032b8e14-5f22-41ad-b350-cb1f5622753a","content":"<p>In many cases,</p>"},{"id":"3d42a470-08e5-4bb1-86f8-80a27c74e965","content":"<p>As a result,</p>"},{"id":"5791ff59-eb15-4c6a-a0fe-fe78fed5cc5e","content":"<p>Additionally,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["032b8e14-5f22-41ad-b350-cb1f5622753a"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The first sentence makes the claim that using grime-eating bacteria has led to &ldquo;impressive results.&rdquo; This sentence supports that claim by describing the specific findings of the biologists&rsquo; experimentation. The transition &ldquo;in many cases&rdquo; fits the context perfectly. </p><p>Choice A is incorrect. This choice uses a disagreement transition. But this sentence actually agrees with the previous sentence. Both claim that grime-eating bacteria are better at cleaning artworks than chemicals. Choice C is incorrect. This choice uses a cause-and-effect transition, which doesn&rsquo;t make sense in context. The fact that the results of the experimentation have been impressive overall doesn&rsquo;t cause the bacteria to have proven more effective. Choice D is incorrect. This choice uses a transition that indicates the addition of a new idea. But this sentence doesn&rsquo;t introduce a new idea. Instead, it elaborates on the same idea laid out in the previous sentence by describing the &ldquo;impressive results&rdquo; in more detail. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-M002$SATQ$, $SATQ$$SATQ$, $SATQ$ac73529d-0adc-4c35-ad69-555965ed8963$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"326017ce","external_id":"db7f27c9-80b1-4168-9dda-b415c1979457","vaultid":"cbff438f-ec3a-4703-9875-3b829508861e","uId":"1331a7b2-aba5-4856-9884-747044a7f94a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>For years, biologists have experimented with using grime-eating bacteria rather than harsh chemicals to clean artworks, and results have been impressive overall. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> these bacterial strains&mdash;which can metabolize centuries&rsquo; worth of oil, glue, dirt, and other surface impurities without creating harmful byproducts&mdash;have proven more effective than traditional chemical cleaning methods.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"6c713a0f-0b50-4f17-947c-1b3557524bd2","content":"<p>However,</p>"},{"id":"032b8e14-5f22-41ad-b350-cb1f5622753a","content":"<p>In many cases,</p>"},{"id":"3d42a470-08e5-4bb1-86f8-80a27c74e965","content":"<p>As a result,</p>"},{"id":"5791ff59-eb15-4c6a-a0fe-fe78fed5cc5e","content":"<p>Additionally,</p>"}],"keys":["032b8e14-5f22-41ad-b350-cb1f5622753a"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The first sentence makes the claim that using grime-eating bacteria has led to &ldquo;impressive results.&rdquo; This sentence supports that claim by describing the specific findings of the biologists&rsquo; experimentation. The transition &ldquo;in many cases&rdquo; fits the context perfectly. </p><p>Choice A is incorrect. This choice uses a disagreement transition. But this sentence actually agrees with the previous sentence. Both claim that grime-eating bacteria are better at cleaning artworks than chemicals. Choice C is incorrect. This choice uses a cause-and-effect transition, which doesn&rsquo;t make sense in context. The fact that the results of the experimentation have been impressive overall doesn&rsquo;t cause the bacteria to have proven more effective. Choice D is incorrect. This choice uses a transition that indicates the addition of a new idea. But this sentence doesn&rsquo;t introduce a new idea. Instead, it elaborates on the same idea laid out in the previous sentence by describing the &ldquo;impressive results&rdquo; in more detail. </p>","parenttemplatename":"OSP-KA-TRA-M002","parenttemplateid":"","templateclusterid":"ac73529d-0adc-4c35-ad69-555965ed8963","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$332e75bf$SATQ$, $SATQ$653bea66-a999-4d76-aa42-cf889190148d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In Annie Dillard&rsquo;s <em>Pilgrim at Tinker Creek</em>&mdash;where, early on, the author marvels at a single goldfish&rsquo;s delicate fins but later winces when imagining a horde of goldfish laying and eating their own eggs&mdash;Dillard struggles to reconcile the complicated juxtapositions of the natural world. <span aria-hidden="true">______</span><span class="sr-only">blank</span> nature&rsquo;s mesmerizing intricacy and pitiless harshness prove inextricably linked for Dillard, like &ldquo;two branches of the same creek.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"21f9c154-4e28-48bc-b517-8af3d2fdf174","content":"<p>To that end,</p>"},{"id":"e7ce0d47-a956-48d3-98de-d09d9bb4e0cf","content":"<p>Ultimately,</p>"},{"id":"da2f4552-e088-45cc-9ea4-4a08137ccea3","content":"<p>Moreover,</p>"},{"id":"151f56d5-1f4e-4cd0-a1ba-f07b43958b73","content":"<p>Hence,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["e7ce0d47-a956-48d3-98de-d09d9bb4e0cf"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. &ldquo;Ultimately&rdquo; logically signals that the information in this sentence&mdash;that, for Dillard, nature&rsquo;s mesmerizing intricacy and pitiless harshness are inextricably linked&mdash;is the final conclusion or realization reached after her struggle to reconcile the juxtapositions of the natural world mentioned in the previous sentence.</p><p>Choice A is incorrect because &ldquo;to that end&rdquo; illogically signals that linking nature&rsquo;s intricacy and harshness was Dillard&rsquo;s deliberate goal or purpose in struggling to reconcile nature&rsquo;s juxtapositions. Instead, the sentence presents her final realization after that struggle. Choice C is incorrect because &ldquo;moreover&rdquo; illogically signals that the information in this sentence merely adds to Dillard&rsquo;s struggle to reconcile nature&rsquo;s juxtapositions mentioned in the previous sentence. Instead, the sentence presents her final realization after that struggle. Choice D is incorrect because &ldquo;hence&rdquo; illogically signals that nature&rsquo;s intricacy and harshness being linked is a direct consequence of Dillard&rsquo;s struggle to reconcile the juxtapositions mentioned in the previous sentence. Instead, the sentence presents her final realization after that struggle.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"332e75bf","external_id":"653bea66-a999-4d76-aa42-cf889190148d","vaultid":null,"uId":"dd946b27-a549-483c-a52f-6dc05b555569","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In Annie Dillard&rsquo;s <em>Pilgrim at Tinker Creek</em>&mdash;where, early on, the author marvels at a single goldfish&rsquo;s delicate fins but later winces when imagining a horde of goldfish laying and eating their own eggs&mdash;Dillard struggles to reconcile the complicated juxtapositions of the natural world. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> nature&rsquo;s mesmerizing intricacy and pitiless harshness prove inextricably linked for Dillard, like &ldquo;two branches of the same creek.&rdquo;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"21f9c154-4e28-48bc-b517-8af3d2fdf174","content":"<p>To that end,</p>"},{"id":"e7ce0d47-a956-48d3-98de-d09d9bb4e0cf","content":"<p>Ultimately,</p>"},{"id":"da2f4552-e088-45cc-9ea4-4a08137ccea3","content":"<p>Moreover,</p>"},{"id":"151f56d5-1f4e-4cd0-a1ba-f07b43958b73","content":"<p>Hence,</p>"}],"keys":["e7ce0d47-a956-48d3-98de-d09d9bb4e0cf"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. &ldquo;Ultimately&rdquo; logically signals that the information in this sentence&mdash;that, for Dillard, nature&rsquo;s mesmerizing intricacy and pitiless harshness are inextricably linked&mdash;is the final conclusion or realization reached after her struggle to reconcile the juxtapositions of the natural world mentioned in the previous sentence.</p><p>Choice A is incorrect because &ldquo;to that end&rdquo; illogically signals that linking nature&rsquo;s intricacy and harshness was Dillard&rsquo;s deliberate goal or purpose in struggling to reconcile nature&rsquo;s juxtapositions. Instead, the sentence presents her final realization after that struggle. Choice C is incorrect because &ldquo;moreover&rdquo; illogically signals that the information in this sentence merely adds to Dillard&rsquo;s struggle to reconcile nature&rsquo;s juxtapositions mentioned in the previous sentence. Instead, the sentence presents her final realization after that struggle. Choice D is incorrect because &ldquo;hence&rdquo; illogically signals that nature&rsquo;s intricacy and harshness being linked is a direct consequence of Dillard&rsquo;s struggle to reconcile the juxtapositions mentioned in the previous sentence. Instead, the sentence presents her final realization after that struggle.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$335bbe3e$SATQ$, $SATQ$7f3e3df2-29e5-4d5b-8f57-55a29038ced2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In his painting <em>At the Cycle-Race Track</em>, Jean Metzinger aims to depict a bike race in four-dimensional space. Of course, Metzinger&rsquo;s painting doesn&rsquo;t technically represent a fourth dimension; humans can only see in three dimensions. <span aria-hidden="true">______</span><span class="sr-only">blank</span> by depicting the race through multiple, simultaneous perspectives, Metzinger offers a fascinating glimpse at what this other universe might look like.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"dfb3a3c4-a554-4d0e-abea-b9a139fb82ff","content":"<p>Moreover,</p>"},{"id":"a9059ddc-f24e-4416-9b9c-a28bfc3b3545","content":"<p>That said,</p>"},{"id":"ca466328-f7e8-4a54-84e8-63d21efe34fc","content":"<p>In other words,</p>"},{"id":"18b63aac-6dc4-4fe6-869e-caaeeab2dae1","content":"<p>For example,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a9059ddc-f24e-4416-9b9c-a28bfc3b3545"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "That said" logically signals that the statement in this sentence&mdash;that Metzinger offers a glimpse of four-dimensional space by depicting multiple, simultaneous perspectives&mdash;is true despite the point in the previous sentence (that Metzinger&rsquo;s painting doesn&rsquo;t technically represent a fourth dimension because humans can only see in three dimensions).</p><p>Choice A is incorrect because "moreover" illogically signals that the information in this sentence merely adds to the previous point about Metzinger&rsquo;s painting. Instead, it provides information that is true despite that previous point. Choice C is incorrect because "in other words" illogically signals that the information in this sentence is a paraphrase or restatement of the previous point about Metzinger&rsquo;s painting. Instead, it provides information that is true despite that previous point. Choice D is incorrect because "for example" illogically signals that the information in this sentence provides an example that supports the previous point about Metzinger&rsquo;s painting. Instead, it provides information that is true despite that previous point.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"335bbe3e","external_id":"7f3e3df2-29e5-4d5b-8f57-55a29038ced2","vaultid":null,"uId":"2b1c68df-04d6-451e-8e3e-708887a40e21","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In his painting <em>At the Cycle-Race Track</em>, Jean Metzinger aims to depict a bike race in four-dimensional space. Of course, Metzinger&rsquo;s painting doesn&rsquo;t technically represent a fourth dimension; humans can only see in three dimensions. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> by depicting the race through multiple, simultaneous perspectives, Metzinger offers a fascinating glimpse at what this other universe might look like.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"dfb3a3c4-a554-4d0e-abea-b9a139fb82ff","content":"<p>Moreover,</p>"},{"id":"a9059ddc-f24e-4416-9b9c-a28bfc3b3545","content":"<p>That said,</p>"},{"id":"ca466328-f7e8-4a54-84e8-63d21efe34fc","content":"<p>In other words,</p>"},{"id":"18b63aac-6dc4-4fe6-869e-caaeeab2dae1","content":"<p>For example,</p>"}],"keys":["a9059ddc-f24e-4416-9b9c-a28bfc3b3545"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"That said\" logically signals that the statement in this sentence&mdash;that Metzinger offers a glimpse of four-dimensional space by depicting multiple, simultaneous perspectives&mdash;is true despite the point in the previous sentence (that Metzinger&rsquo;s painting doesn&rsquo;t technically represent a fourth dimension because humans can only see in three dimensions).</p><p>Choice A is incorrect because \"moreover\" illogically signals that the information in this sentence merely adds to the previous point about Metzinger&rsquo;s painting. Instead, it provides information that is true despite that previous point. Choice C is incorrect because \"in other words\" illogically signals that the information in this sentence is a paraphrase or restatement of the previous point about Metzinger&rsquo;s painting. Instead, it provides information that is true despite that previous point. Choice D is incorrect because \"for example\" illogically signals that the information in this sentence provides an example that supports the previous point about Metzinger&rsquo;s painting. Instead, it provides information that is true despite that previous point.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669210,"updateDate":1743430669210}$SATQ$::jsonb, 1743430669210, 1743430669210),
    ($SATQ$34a5ba1c$SATQ$, $SATQ$313e715b-9a8c-4ef8-a32e-fe47bb7d02d3$SATQ$::uuid, $SATQ$4ab608dd-a248-476b-b1f2-7090964ef65a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>By 1936, Spanish Romani dancer Carmen Amaya was known all over Spain for her powerful style of flamenco dancing. However, in July of that year, the outbreak of the Spanish Civil War made it difficult for her to perform in her home country. <span aria-hidden="true">______</span><span class="sr-only">blank</span> Amaya left Spain to perform abroad, dancing for audiences across North and South America.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"11963a56-229d-4c09-b845-e011489a7755","content":"<p>In comparison,</p>"},{"id":"a6e5243d-ae07-4d0a-b8fc-05aa095c45de","content":"<p>As a result,</p>"},{"id":"5eca2895-0f1e-4c13-abb4-ea062e18bc44","content":"<p>First of all,</p>"},{"id":"9fa1b5d9-4d29-4e26-9bd9-918324eb0ba6","content":"<p>For example,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a6e5243d-ae07-4d0a-b8fc-05aa095c45de"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. &ldquo;As a result&rdquo; logically signals that the information in this sentence about Amaya leaving Spain to perform abroad is a result of the previous information about the Spanish Civil War. </p><p>Choice A is incorrect because &ldquo;in comparison&rdquo; illogically signals that the information in this sentence is being compared to the previous information about the Spanish Civil War. Instead, Amaya leaving Spain is a result of that war. Choice C is incorrect because &ldquo;first of all&rdquo; illogically signals that the information in this sentence is the beginning of a sequence of events. Instead, Amaya leaving Spain is a result of the event (the outbreak of war) described in the previous sentence. Choice D is incorrect because &ldquo;for example&rdquo; illogically signals that the information in this sentence is an example supporting the previous statement about the Spanish Civil War. Instead, Amaya leaving Spain is a result of that war. </p>$SATQ$, false, 0, $SATQ$OSP-259-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$95165274-41ad-4651-8106-1425ab4bd1e1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"34a5ba1c","external_id":"313e715b-9a8c-4ef8-a32e-fe47bb7d02d3","vaultid":"4ab608dd-a248-476b-b1f2-7090964ef65a","uId":"c7fd8f55-a863-46e3-aa83-032bfe28106d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>By 1936, Spanish Romani dancer Carmen Amaya was known all over Spain for her powerful style of flamenco dancing. However, in July of that year, the outbreak of the Spanish Civil War made it difficult for her to perform in her home country. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Amaya left Spain to perform abroad, dancing for audiences across North and South America.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"11963a56-229d-4c09-b845-e011489a7755","content":"<p>In comparison,</p>"},{"id":"a6e5243d-ae07-4d0a-b8fc-05aa095c45de","content":"<p>As a result,</p>"},{"id":"5eca2895-0f1e-4c13-abb4-ea062e18bc44","content":"<p>First of all,</p>"},{"id":"9fa1b5d9-4d29-4e26-9bd9-918324eb0ba6","content":"<p>For example,</p>"}],"keys":["a6e5243d-ae07-4d0a-b8fc-05aa095c45de"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. &ldquo;As a result&rdquo; logically signals that the information in this sentence about Amaya leaving Spain to perform abroad is a result of the previous information about the Spanish Civil War. </p><p>Choice A is incorrect because &ldquo;in comparison&rdquo; illogically signals that the information in this sentence is being compared to the previous information about the Spanish Civil War. Instead, Amaya leaving Spain is a result of that war. Choice C is incorrect because &ldquo;first of all&rdquo; illogically signals that the information in this sentence is the beginning of a sequence of events. Instead, Amaya leaving Spain is a result of the event (the outbreak of war) described in the previous sentence. Choice D is incorrect because &ldquo;for example&rdquo; illogically signals that the information in this sentence is an example supporting the previous statement about the Spanish Civil War. Instead, Amaya leaving Spain is a result of that war. </p>","parenttemplatename":"OSP-259-TRA","parenttemplateid":"","templateclusterid":"95165274-41ad-4651-8106-1425ab4bd1e1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959334,"updateDate":1691007959334}$SATQ$::jsonb, 1691007959334, 1691007959334),
    ($SATQ$34e1124f$SATQ$, $SATQ$65ead50b-41d4-4ae3-b8d9-a0e3cbd6111c$SATQ$::uuid, $SATQ$e148244c-29cb-43ad-b605-c77f0d1e09e6$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>In geology, an Aeolian landform is one that has been created by the wind.</li>
<li>In Greek mythology, Aeolus is the keeper of the winds.</li>
<li>Aeolian landforms are created when the wind erodes, transports, or deposits material.</li>
<li>A mushroom rock is a rock formation in which the top is wider than the base.</li>
<li>A mushroom rock can be formed when the wind erodes the base and the top at different rates.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to provide an explanation and an example of Aeolian landforms. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"cab186b8-b8a4-4526-8173-ba72af9ee938","content":"<p>Aeolian landforms are created by different wind-based processes; for example, some are created by wind erosion.</p>"},{"id":"39468365-49e3-4a92-a5c1-1be26e4c31c8","content":"<p>Aeolian landforms&mdash;landforms created by the wind&mdash;include the mushroom rock, a rock formation in which the wind erodes the base of the rock faster than the top.</p>"},{"id":"8b7f8d78-cff1-484b-8349-b0dd12b33a99","content":"<p>Erosion, transportation, and deposition are three examples of how the wind can create Aeolian landforms and mushroom rocks.</p>"},{"id":"95c268ec-184a-4d7c-b6e6-ce7df8bdaac4","content":"<p>A mushroom rock is a rock formation that owes its shape to the wind, a natural force associated with Aeolus in Greek mythology.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["39468365-49e3-4a92-a5c1-1be26e4c31c8"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence provides an explanation and an example of Aeolian landforms, explaining that they are landforms created by wind and offering the mushroom rock as an example. </p><p>Choice A is incorrect. The sentence explains that Aeolian landforms are created by wind but does not provide an example of any specific Aeolian landforms. Rather, the example it provides is of a wind-based process. Choice C is incorrect. While the sentence provides a partial explanation of Aeolian landforms, noting that they are created by the wind, it does not effectively provide an example. The sentence seems to indicate that mushroom rocks, rather than being an example of Aeolian landforms, are distinct from them. Choice D is incorrect. While the sentence provides an explanation of a mushroom rock, which is a specific example of an Aeolian landform, it doesn&rsquo;t provide an explanation of Aeolian landforms in general. </p>$SATQ$, false, 0, $SATQ$OSP-722-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$1caf3540-8a4d-4418-af0c-ad788b1de1c9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"34e1124f","external_id":"65ead50b-41d4-4ae3-b8d9-a0e3cbd6111c","vaultid":"e148244c-29cb-43ad-b605-c77f0d1e09e6","uId":"a78c15ea-5ea3-4b06-b317-d67d8c704e40","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>In geology, an Aeolian landform is one that has been created by the wind.</li>\n<li>In Greek mythology, Aeolus is the keeper of the winds.</li>\n<li>Aeolian landforms are created when the wind erodes, transports, or deposits material.</li>\n<li>A mushroom rock is a rock formation in which the top is wider than the base.</li>\n<li>A mushroom rock can be formed when the wind erodes the base and the top at different rates.</li>\n</ul>","stem":"<p>The student wants to provide an explanation and an example of Aeolian landforms. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"cab186b8-b8a4-4526-8173-ba72af9ee938","content":"<p>Aeolian landforms are created by different wind-based processes; for example, some are created by wind erosion.</p>"},{"id":"39468365-49e3-4a92-a5c1-1be26e4c31c8","content":"<p>Aeolian landforms&mdash;landforms created by the wind&mdash;include the mushroom rock, a rock formation in which the wind erodes the base of the rock faster than the top.</p>"},{"id":"8b7f8d78-cff1-484b-8349-b0dd12b33a99","content":"<p>Erosion, transportation, and deposition are three examples of how the wind can create Aeolian landforms and mushroom rocks.</p>"},{"id":"95c268ec-184a-4d7c-b6e6-ce7df8bdaac4","content":"<p>A mushroom rock is a rock formation that owes its shape to the wind, a natural force associated with Aeolus in Greek mythology.</p>"}],"keys":["39468365-49e3-4a92-a5c1-1be26e4c31c8"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence provides an explanation and an example of Aeolian landforms, explaining that they are landforms created by wind and offering the mushroom rock as an example. </p><p>Choice A is incorrect. The sentence explains that Aeolian landforms are created by wind but does not provide an example of any specific Aeolian landforms. Rather, the example it provides is of a wind-based process. Choice C is incorrect. While the sentence provides a partial explanation of Aeolian landforms, noting that they are created by the wind, it does not effectively provide an example. The sentence seems to indicate that mushroom rocks, rather than being an example of Aeolian landforms, are distinct from them. Choice D is incorrect. While the sentence provides an explanation of a mushroom rock, which is a specific example of an Aeolian landform, it doesn&rsquo;t provide an explanation of Aeolian landforms in general. </p>","parenttemplatename":"OSP-722-SYN","parenttemplateid":"","templateclusterid":"1caf3540-8a4d-4418-af0c-ad788b1de1c9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959348,"updateDate":1691007959348}$SATQ$::jsonb, 1691007959348, 1691007959348),
    ($SATQ$35507eba$SATQ$, $SATQ$84d99c7c-2ee6-4b7d-b5e5-8819efadbec0$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Pointillism is a painting technique in which small, distinct dots of color are applied in patterns to form an image.</li>
<li>Betty Acquah is an artist from Ghana who uses pointillism in her work.</li>
<li>&ldquo;By extending dabs of color in the subject matter into the background and vice-versa, an illusion of movement is created,&rdquo; she says about pointillism.</li>
<li>Her work often portrays Ghanaian women, whom she sees as the &ldquo;unsung heroines of the Ghanaian Republic.&rdquo;</li>
<li>Her pointillist painting &ldquo;Exquisite&rdquo; (2016) features five dancing women twirling their skirts.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to provide a quotation from Acquah that explains why she used pointillism in &ldquo;Exquisite.&rdquo; Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"81e8555d-c9df-4a9f-b038-9df948b1ce8c","content":"<p>In painting &ldquo;Exquisite,&rdquo; Acquah applied pointillism to create what she called an &ldquo;illusion of movement&rdquo; within the painting&rsquo;s five dancing women and their twirling skirts.</p>"},{"id":"c6239fe0-2dec-4170-9e8d-397e055fe9af","content":"<p>Pointillism, the technique used in Acquah&rsquo;s &ldquo;Exquisite,&rdquo; involves the application of small, distinct dots of color.</p>"},{"id":"75d62967-4de0-4dd5-b54f-140c83b17708","content":"<p>In &ldquo;Exquisite,&rdquo; Acquah uses a technique that she says involves &ldquo;extending dabs of color in the subject matter into the background and vice-versa.&rdquo;</p>"},{"id":"b89fac5f-1ea3-41b8-8b34-7438ddbdd3e8","content":"<p>&ldquo;Exquisite&rdquo; portrays Acquah&rsquo;s fellow Ghanaian women as she sees them: the &ldquo;unsung heroes of the Ghanaian Republic.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["81e8555d-c9df-4a9f-b038-9df948b1ce8c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence provides Acquah&rsquo;s quotation about pointillism&rsquo;s "illusion of movement" to explain that she used pointillism to create the illusion of movement in her painting of women dancing.</p><p>Choice B is incorrect. The sentence explains pointillism and indicates that Acquah used the technique in her painting, but it doesn&rsquo;t provide a quotation or explain why. Choice C is incorrect. While the sentence provides a quotation from Acquah about pointillism, the quotation merely describes a specific aspect of the technique; the sentence doesn&rsquo;t explain why Acquah used pointillism in her painting. Choice D is incorrect. While the sentence provides a quotation from Acquah, the quotation illustrates Acquah&rsquo;s views on Ghanaian women; the sentence doesn&rsquo;t explain why Acquah used pointillism in her painting.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"35507eba","external_id":"84d99c7c-2ee6-4b7d-b5e5-8819efadbec0","vaultid":null,"uId":"720c649f-870b-478a-aff8-773bcda86876","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Pointillism is a painting technique in which small, distinct dots of color are applied in patterns to form an image.</li>\n<li>Betty Acquah is an artist from Ghana who uses pointillism in her work.</li>\n<li>&ldquo;By extending dabs of color in the subject matter into the background and vice-versa, an illusion of movement is created,&rdquo; she says about pointillism.</li>\n<li>Her work often portrays Ghanaian women, whom she sees as the &ldquo;unsung heroines of the Ghanaian Republic.&rdquo;</li>\n<li>Her pointillist painting &ldquo;Exquisite&rdquo; (2016) features five dancing women twirling their skirts.</li>\n</ul>","stem":"<p>The student wants to provide a quotation from Acquah that explains why she used pointillism in &ldquo;Exquisite.&rdquo; Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"81e8555d-c9df-4a9f-b038-9df948b1ce8c","content":"<p>In painting &ldquo;Exquisite,&rdquo; Acquah applied pointillism to create what she called an &ldquo;illusion of movement&rdquo; within the painting&rsquo;s five dancing women and their twirling skirts.</p>"},{"id":"c6239fe0-2dec-4170-9e8d-397e055fe9af","content":"<p>Pointillism, the technique used in Acquah&rsquo;s &ldquo;Exquisite,&rdquo; involves the application of small, distinct dots of color.</p>"},{"id":"75d62967-4de0-4dd5-b54f-140c83b17708","content":"<p>In &ldquo;Exquisite,&rdquo; Acquah uses a technique that she says involves &ldquo;extending dabs of color in the subject matter into the background and vice-versa.&rdquo;</p>"},{"id":"b89fac5f-1ea3-41b8-8b34-7438ddbdd3e8","content":"<p>&ldquo;Exquisite&rdquo; portrays Acquah&rsquo;s fellow Ghanaian women as she sees them: the &ldquo;unsung heroes of the Ghanaian Republic.&rdquo;</p>"}],"keys":["81e8555d-c9df-4a9f-b038-9df948b1ce8c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence provides Acquah&rsquo;s quotation about pointillism&rsquo;s \"illusion of movement\" to explain that she used pointillism to create the illusion of movement in her painting of women dancing.</p><p>Choice B is incorrect. The sentence explains pointillism and indicates that Acquah used the technique in her painting, but it doesn&rsquo;t provide a quotation or explain why. Choice C is incorrect. While the sentence provides a quotation from Acquah about pointillism, the quotation merely describes a specific aspect of the technique; the sentence doesn&rsquo;t explain why Acquah used pointillism in her painting. Choice D is incorrect. While the sentence provides a quotation from Acquah, the quotation illustrates Acquah&rsquo;s views on Ghanaian women; the sentence doesn&rsquo;t explain why Acquah used pointillism in her painting.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323032,"updateDate":1730147323032}$SATQ$::jsonb, 1730147323032, 1730147323032),
    ($SATQ$37957752$SATQ$, $SATQ$6ac65687-dbeb-45fe-9260-d7cbe31177e1$SATQ$::uuid, $SATQ$5f133cad-84e5-47ea-b320-742f50d6f6a5$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>As biologist Terrie Williams has documented, deep dives present a challenge for seals and other marine mammals. A seal must exert enough energy to propel itself hundreds of meters downward, while keeping its heart rate low enough that it doesn&rsquo;t run out of oxygen while underwater. <span aria-hidden="true">______</span><span class="sr-only">blank</span> a seal moves its flippers as little as possible on a deep dive, gliding to conserve energy.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"4b16b08d-614c-46c2-b303-577da3159c8b","content":"<p>In the first place,</p>"},{"id":"d0056231-c0fa-4710-8136-5da82dd7a876","content":"<p>On the other hand,</p>"},{"id":"b9ae48ea-673b-413a-9a43-606f4900f6ed","content":"<p>For this reason,</p>"},{"id":"a82cee71-be79-4ea4-a3b5-0be38cbf3c21","content":"<p>In comparison,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b9ae48ea-673b-413a-9a43-606f4900f6ed"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;For this reason&rdquo; logically signals that the behavior described in this sentence is a consequence of the information about seals in the previous sentence. That is, a seal moves its flippers as little as possible during a deep dive because it needs to keep its heart rate low enough that it does not run out of oxygen.&nbsp;</p><p>Choice A is incorrect because &ldquo;in the first place&rdquo; illogically signals that this sentence is the first point in a discussion. Instead, the sentence describes a behavior that is a consequence of the previous information about seals. &nbsp;Choice B is incorrect because &ldquo;on the other hand&rdquo; illogically signals that the behavior described in this sentence contrasts with the previous information about seals. Instead, it is a consequence of that information. Choice D is incorrect because &ldquo;in comparison&rdquo; illogically signals that the behavior described in this sentence is being compared to the previous information about seals. Instead, it is a consequence of that information.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-255-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$4cb7065e-e5f6-4e8a-8a92-80e818980b15$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"37957752","external_id":"6ac65687-dbeb-45fe-9260-d7cbe31177e1","vaultid":"5f133cad-84e5-47ea-b320-742f50d6f6a5","uId":"ca0a1384-eb57-4d1a-9e09-112c6c8e1712","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>As biologist Terrie Williams has documented, deep dives present a challenge for seals and other marine mammals. A seal must exert enough energy to propel itself hundreds of meters downward, while keeping its heart rate low enough that it doesn&rsquo;t run out of oxygen while underwater. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a seal moves its flippers as little as possible on a deep dive, gliding to conserve energy.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"4b16b08d-614c-46c2-b303-577da3159c8b","content":"<p>In the first place,</p>"},{"id":"d0056231-c0fa-4710-8136-5da82dd7a876","content":"<p>On the other hand,</p>"},{"id":"b9ae48ea-673b-413a-9a43-606f4900f6ed","content":"<p>For this reason,</p>"},{"id":"a82cee71-be79-4ea4-a3b5-0be38cbf3c21","content":"<p>In comparison,</p>"}],"keys":["b9ae48ea-673b-413a-9a43-606f4900f6ed"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;For this reason&rdquo; logically signals that the behavior described in this sentence is a consequence of the information about seals in the previous sentence. That is, a seal moves its flippers as little as possible during a deep dive because it needs to keep its heart rate low enough that it does not run out of oxygen.&nbsp;</p><p>Choice A is incorrect because &ldquo;in the first place&rdquo; illogically signals that this sentence is the first point in a discussion. Instead, the sentence describes a behavior that is a consequence of the previous information about seals. &nbsp;Choice B is incorrect because &ldquo;on the other hand&rdquo; illogically signals that the behavior described in this sentence contrasts with the previous information about seals. Instead, it is a consequence of that information. Choice D is incorrect because &ldquo;in comparison&rdquo; illogically signals that the behavior described in this sentence is being compared to the previous information about seals. Instead, it is a consequence of that information.&nbsp;</p>","parenttemplatename":"OSP-255-TRA","parenttemplateid":"","templateclusterid":"4cb7065e-e5f6-4e8a-8a92-80e818980b15","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959333,"updateDate":1691007959333}$SATQ$::jsonb, 1691007959333, 1691007959333),
    ($SATQ$37ec26e7$SATQ$, $SATQ$4c24e768-d3fc-4bd8-ba35-08de02d100b8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In order to create the Global Positioning System (GPS), scientists had to develop an accurate mathematical model of Earth&rsquo;s shape that accounted for various forces, such as tides. <span aria-hidden="true">______</span><span class="sr-only">blank</span> it was mathematician Gladys West who wrote the computer program that could perform these necessary calculations.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"980a320f-17f1-4c48-aa16-acca80305b16","content":"<p>Ultimately,</p>"},{"id":"926d0b49-a900-4b0b-8ce7-48f4691be620","content":"<p>In other words,</p>"},{"id":"5138bc76-7f43-4a72-bede-00d362c23a18","content":"<p>Secondly,</p>"},{"id":"c315eca9-b6b6-4eb6-ad5d-ad4cdf283bf2","content":"<p>In addition,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["980a320f-17f1-4c48-aa16-acca80305b16"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "Ultimately" logically signals that West&rsquo;s completion of the computer program was the conclusion of the process described in the previous sentence, in which scientists working on GPS sought to develop a mathematical model of Earth.</p><p>Choice B is incorrect because "in other words" illogically signals that the information about West&rsquo;s program is a restatement of the information about the scientists&rsquo; efforts to develop a mathematical model of Earth. Instead, West&rsquo;s program was the conclusion of those efforts. Choice C is incorrect because "secondly" illogically signals that West&rsquo;s completion of the computer program was merely the next step in the scientists&rsquo; efforts to develop a mathematical model of Earth. Instead, West&rsquo;s program was the conclusion of those efforts. Choice D is incorrect because "in addition" illogically signals that West&rsquo;s completion of the computer program was merely additional information related to the scientists&rsquo; work on GPS. Instead, West&rsquo;s program was the conclusion of the scientists&rsquo; efforts to develop a mathematical model of Earth.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"37ec26e7","external_id":"4c24e768-d3fc-4bd8-ba35-08de02d100b8","vaultid":null,"uId":"81837902-e7c6-4c04-9241-b30e1d0960fe","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In order to create the Global Positioning System (GPS), scientists had to develop an accurate mathematical model of Earth&rsquo;s shape that accounted for various forces, such as tides. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> it was mathematician Gladys West who wrote the computer program that could perform these necessary calculations.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"980a320f-17f1-4c48-aa16-acca80305b16","content":"<p>Ultimately,</p>"},{"id":"926d0b49-a900-4b0b-8ce7-48f4691be620","content":"<p>In other words,</p>"},{"id":"5138bc76-7f43-4a72-bede-00d362c23a18","content":"<p>Secondly,</p>"},{"id":"c315eca9-b6b6-4eb6-ad5d-ad4cdf283bf2","content":"<p>In addition,</p>"}],"keys":["980a320f-17f1-4c48-aa16-acca80305b16"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"Ultimately\" logically signals that West&rsquo;s completion of the computer program was the conclusion of the process described in the previous sentence, in which scientists working on GPS sought to develop a mathematical model of Earth.</p><p>Choice B is incorrect because \"in other words\" illogically signals that the information about West&rsquo;s program is a restatement of the information about the scientists&rsquo; efforts to develop a mathematical model of Earth. Instead, West&rsquo;s program was the conclusion of those efforts. Choice C is incorrect because \"secondly\" illogically signals that West&rsquo;s completion of the computer program was merely the next step in the scientists&rsquo; efforts to develop a mathematical model of Earth. Instead, West&rsquo;s program was the conclusion of those efforts. Choice D is incorrect because \"in addition\" illogically signals that West&rsquo;s completion of the computer program was merely additional information related to the scientists&rsquo; work on GPS. Instead, West&rsquo;s program was the conclusion of the scientists&rsquo; efforts to develop a mathematical model of Earth.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$3831f2d7$SATQ$, $SATQ$e01ca56c-1c25-4e49-934b-d6d844fdf17b$SATQ$::uuid, $SATQ$d2501a79-a9b0-4765-b2d9-5a2fee24566b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Arkansas aviator Louise Thaden was already a record breaker when she won the inaugural National Women&rsquo;s Air Derby, a race from California to Ohio, in August of 1929. <span aria-hidden="true">______</span><span class="sr-only">blank</span> in December of 1928, Thaden had set an aviation record when she reached an altitude of 20,269 feet in a Travel Air biplane.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"f467cd02-1799-4187-b732-a964ceb5e2e4","content":"<p>Earlier,</p>"},{"id":"6f76fd94-6726-4051-af00-7dd0c9374157","content":"<p>However,</p>"},{"id":"27a36293-b504-4dfb-882e-0680c3adb1e6","content":"<p>Next,</p>"},{"id":"51c12915-f8d7-48c4-864c-8c7d25a78217","content":"<p>As a result,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["f467cd02-1799-4187-b732-a964ceb5e2e4"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. This choice uses a transition that indicates a shift back in time. Since the first sentence talks about Thaden&rsquo;s race win in 1929 and the second shifts back to talking about her record in 1928, this makes the most sense here.</p><p>Choice B is incorrect. This choice uses a disagreement transition. But this sentence actually agrees with and expands on the previous sentence by describing the earlier record that Thaden had "already" held. Choice C is incorrect. This choice uses a transition that indicates a shift forward in time, which doesn&rsquo;t make sense here. A record in 1928 didn&rsquo;t come after Thaden&rsquo;s race win in 1929. Choice D is incorrect. This choice uses a cause-and-effect transition, which doesn&rsquo;t make sense in this context&mdash;an event in 1929 can&rsquo;t cause something in 1928.</p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-E007$SATQ$, $SATQ$$SATQ$, $SATQ$8062a718-171a-424a-a881-a5990f288e78$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3831f2d7","external_id":"e01ca56c-1c25-4e49-934b-d6d844fdf17b","vaultid":"d2501a79-a9b0-4765-b2d9-5a2fee24566b","uId":"b88611c3-4357-4430-96a8-fe1d8a1c391d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Arkansas aviator Louise Thaden was already a record breaker when she won the inaugural National Women&rsquo;s Air Derby, a race from California to Ohio, in August of 1929. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in December of 1928, Thaden had set an aviation record when she reached an altitude of 20,269 feet in a Travel Air biplane.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"f467cd02-1799-4187-b732-a964ceb5e2e4","content":"<p>Earlier,</p>"},{"id":"6f76fd94-6726-4051-af00-7dd0c9374157","content":"<p>However,</p>"},{"id":"27a36293-b504-4dfb-882e-0680c3adb1e6","content":"<p>Next,</p>"},{"id":"51c12915-f8d7-48c4-864c-8c7d25a78217","content":"<p>As a result,</p>"}],"keys":["f467cd02-1799-4187-b732-a964ceb5e2e4"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. This choice uses a transition that indicates a shift back in time. Since the first sentence talks about Thaden&rsquo;s race win in 1929 and the second shifts back to talking about her record in 1928, this makes the most sense here.</p><p>Choice B is incorrect. This choice uses a disagreement transition. But this sentence actually agrees with and expands on the previous sentence by describing the earlier record that Thaden had \"already\" held. Choice C is incorrect. This choice uses a transition that indicates a shift forward in time, which doesn&rsquo;t make sense here. A record in 1928 didn&rsquo;t come after Thaden&rsquo;s race win in 1929. Choice D is incorrect. This choice uses a cause-and-effect transition, which doesn&rsquo;t make sense in this context&mdash;an event in 1929 can&rsquo;t cause something in 1928.</p>","parenttemplatename":"OSP-KA-TRA-E007","parenttemplateid":"","templateclusterid":"8062a718-171a-424a-a881-a5990f288e78","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$388b45aa$SATQ$, $SATQ$c8cd8993-74e1-4208-a541-f35ff4dbfeda$SATQ$::uuid, $SATQ$48748156-6b4f-460f-9383-0a0a0acfd25a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Establishing Coordinated Universal Time (UTC) is no easy task. Each month, readings of a single second from atomic clocks around the world are taken and sent to the International Bureau of Weights and Measures (BIPM) in France. <span aria-hidden="true">______</span><span class="sr-only">blank</span> BIPM metrologists perform the meticulous work of assembling these minutely disparate readings into a globally shared time standard.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"7141a515-befb-41e3-a3b5-752e29fbb08c","content":"<p>There,</p>"},{"id":"b488ed37-313d-45fa-a384-8316387dab7f","content":"<p>In particular,</p>"},{"id":"9ed153be-085a-4648-b325-e7da8d444742","content":"<p>For example,</p>"},{"id":"fe99f170-d9c9-4c84-8537-bfe67a5524cd","content":"<p>Conversely,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["7141a515-befb-41e3-a3b5-752e29fbb08c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "There" indicates that the work of calculating Coordinated Universal Time takes place at the International Bureau of Weights and Measures in France. Because "there" indicates a location, it fits the context perfectly.</p><p>Choice B is incorrect. This choice uses an exemplification transition, which doesn&rsquo;t make sense here. This sentence is describing where the work of coordinating Coordinated Universal Time takes place, not giving an example of the work described in the previous sentence. Choice C is incorrect. This choice uses an exemplification transition, which doesn&rsquo;t make sense here. This sentence is describing where the work of coordinating Coordinated Universal Time takes place, not giving an example of the work described in the previous sentence. Choice D is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous sentence. They both describe the work involved in calculating Coordinated Universal Time.</p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-M010$SATQ$, $SATQ$$SATQ$, $SATQ$2ff0a3a6-db93-40bb-ae6f-1881d60971ce$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"388b45aa","external_id":"c8cd8993-74e1-4208-a541-f35ff4dbfeda","vaultid":"48748156-6b4f-460f-9383-0a0a0acfd25a","uId":"7ce750cf-3dee-4ea5-8fca-43cdc8e83b69","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Establishing Coordinated Universal Time (UTC) is no easy task. Each month, readings of a single second from atomic clocks around the world are taken and sent to the International Bureau of Weights and Measures (BIPM) in France. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> BIPM metrologists perform the meticulous work of assembling these minutely disparate readings into a globally shared time standard.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"7141a515-befb-41e3-a3b5-752e29fbb08c","content":"<p>There,</p>"},{"id":"b488ed37-313d-45fa-a384-8316387dab7f","content":"<p>In particular,</p>"},{"id":"9ed153be-085a-4648-b325-e7da8d444742","content":"<p>For example,</p>"},{"id":"fe99f170-d9c9-4c84-8537-bfe67a5524cd","content":"<p>Conversely,</p>"}],"keys":["7141a515-befb-41e3-a3b5-752e29fbb08c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"There\" indicates that the work of calculating Coordinated Universal Time takes place at the International Bureau of Weights and Measures in France. Because \"there\" indicates a location, it fits the context perfectly.</p><p>Choice B is incorrect. This choice uses an exemplification transition, which doesn&rsquo;t make sense here. This sentence is describing where the work of coordinating Coordinated Universal Time takes place, not giving an example of the work described in the previous sentence. Choice C is incorrect. This choice uses an exemplification transition, which doesn&rsquo;t make sense here. This sentence is describing where the work of coordinating Coordinated Universal Time takes place, not giving an example of the work described in the previous sentence. Choice D is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous sentence. They both describe the work involved in calculating Coordinated Universal Time.</p>","parenttemplatename":"OSP-KA-TRA-M010","parenttemplateid":"","templateclusterid":"2ff0a3a6-db93-40bb-ae6f-1881d60971ce","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959374,"updateDate":1691007959374}$SATQ$::jsonb, 1691007959374, 1691007959374),
    ($SATQ$39ccb463$SATQ$, $SATQ$2a121475-3531-4130-9a6f-9b4b2ac0cc54$SATQ$::uuid, $SATQ$b75282c1-91be-4a1e-8b40-8f1af9805a8e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The <em>Atlantic Monthly</em> magazine was first published in 1857.</li>
<li>The magazine focused on politics, art, and literature.</li>
<li>In 2019, historian Cathryn Halverson published the book <em>Faraway Women and the &ldquo;Atlantic Monthly.&rdquo;</em></li>
<li>Its subject is female authors whose autobiographies appeared in the magazine in the early 1900s.</li>
<li>One of the authors discussed is Juanita Harrison.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to introduce Cathryn Halverson&rsquo;s book to an audience already familiar with the <em>Atlantic Monthly</em>. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"ba968417-37c6-4b49-9e93-dcfb4b18972c","content":"<p>Cathryn Halverson&rsquo;s <em>Faraway Women and the &ldquo;Atlantic</em> <em>Monthly&rdquo;</em>&nbsp; discusses female authors whose autobiographies appeared in the magazine<em> </em>in the early 1900s.</p>"},{"id":"c11cabbc-c0bb-4fdd-9bda-42b278e8efca","content":"<p>A magazine called the <em>Atlantic Monthly</em>, referred to in Cathryn Halverson&rsquo;s book title, was first published in 1857.</p>"},{"id":"a6695452-9a79-426d-9970-35d811e3b1c3","content":"<p><em>Faraway Women and the &ldquo;Atlantic Monthly&rdquo;</em>&nbsp; features contributors to the <em>Atlantic Monthly</em>, first published in 1857 as a magazine focusing on politics, art, and literature.&nbsp;</p>"},{"id":"5e0a6916-2bf4-4b1c-8509-a93b6f458569","content":"<p>An author discussed by Cathryn Halverson is Juanita Harrison, whose autobiography appeared in the <em>Atlantic Monthly</em> in the early 1900s.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ba968417-37c6-4b49-9e93-dcfb4b18972c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence effectively introduces Cathryn Halverson&rsquo;s book to an audience already familiar with the <em>Atlantic Monthly</em>, noting the title of Halverson&rsquo;s book and describing its content without providing background information about the <em>Atlantic Monthly</em>. </p><p>Choice B is incorrect. The sentence introduces the <em>Atlantic Monthly</em> and mentions that it&rsquo;s referred to in Cathryn Halverson&rsquo;s book title; it doesn&rsquo;t effectively introduce Halverson&rsquo;s book. Choice C is incorrect. The sentence assumes that the audience is unfamiliar with the <em>Atlantic Monthly</em>, providing background information about the magazine; it doesn&rsquo;t effectively introduce Halverson&rsquo;s book to an audience already familiar with the <em>Atlantic Monthly</em>. Choice D is incorrect. While the sentence assumes that the audience is familiar with the <em>Atlantic Monthly</em>, it doesn&rsquo;t effectively introduce Cathryn Halverson&rsquo;s book. </p>$SATQ$, false, 0, $SATQ$OSP-766-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$be723af8-c945-464e-b8b7-90353f02eaa6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"39ccb463","external_id":"2a121475-3531-4130-9a6f-9b4b2ac0cc54","vaultid":"b75282c1-91be-4a1e-8b40-8f1af9805a8e","uId":"06affb0d-2471-47de-83b4-660d0ef79e8e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The <em>Atlantic Monthly</em> magazine was first published in 1857.</li>\n<li>The magazine focused on politics, art, and literature.</li>\n<li>In 2019, historian Cathryn Halverson published the book <em>Faraway Women and the &ldquo;Atlantic Monthly.&rdquo;</em></li>\n<li>Its subject is female authors whose autobiographies appeared in the magazine in the early 1900s.</li>\n<li>One of the authors discussed is Juanita Harrison.</li>\n</ul>","stem":"<p>The student wants to introduce Cathryn Halverson&rsquo;s book to an audience already familiar with the <em>Atlantic Monthly</em>. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"ba968417-37c6-4b49-9e93-dcfb4b18972c","content":"<p>Cathryn Halverson&rsquo;s <em>Faraway Women and the &ldquo;Atlantic</em> <em>Monthly&rdquo;</em>&nbsp; discusses female authors whose autobiographies appeared in the magazine<em> </em>in the early 1900s.</p>"},{"id":"c11cabbc-c0bb-4fdd-9bda-42b278e8efca","content":"<p>A magazine called the <em>Atlantic Monthly</em>, referred to in Cathryn Halverson&rsquo;s book title, was first published in 1857.</p>"},{"id":"a6695452-9a79-426d-9970-35d811e3b1c3","content":"<p><em>Faraway Women and the &ldquo;Atlantic Monthly&rdquo;</em>&nbsp; features contributors to the <em>Atlantic Monthly</em>, first published in 1857 as a magazine focusing on politics, art, and literature.&nbsp;</p>"},{"id":"5e0a6916-2bf4-4b1c-8509-a93b6f458569","content":"<p>An author discussed by Cathryn Halverson is Juanita Harrison, whose autobiography appeared in the <em>Atlantic Monthly</em> in the early 1900s.</p>"}],"keys":["ba968417-37c6-4b49-9e93-dcfb4b18972c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence effectively introduces Cathryn Halverson&rsquo;s book to an audience already familiar with the <em>Atlantic Monthly</em>, noting the title of Halverson&rsquo;s book and describing its content without providing background information about the <em>Atlantic Monthly</em>. </p><p>Choice B is incorrect. The sentence introduces the <em>Atlantic Monthly</em> and mentions that it&rsquo;s referred to in Cathryn Halverson&rsquo;s book title; it doesn&rsquo;t effectively introduce Halverson&rsquo;s book. Choice C is incorrect. The sentence assumes that the audience is unfamiliar with the <em>Atlantic Monthly</em>, providing background information about the magazine; it doesn&rsquo;t effectively introduce Halverson&rsquo;s book to an audience already familiar with the <em>Atlantic Monthly</em>. Choice D is incorrect. While the sentence assumes that the audience is familiar with the <em>Atlantic Monthly</em>, it doesn&rsquo;t effectively introduce Cathryn Halverson&rsquo;s book. </p>","parenttemplatename":"OSP-766-SYN","parenttemplateid":"","templateclusterid":"be723af8-c945-464e-b8b7-90353f02eaa6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$39d1a519$SATQ$, $SATQ$ca657b0e-f012-43f4-a83e-4ab1fc4e2828$SATQ$::uuid, $SATQ$aba47076-5537-4e5f-93cd-aeaef6ba4805$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>To discover which fruit varieties were grown in Italy&rsquo;s Umbria region before the introduction of industrial farming, botanist Isabella Dalla Ragione often turns to centuries-old lists of cooking ingredients. <span aria-hidden="true">______</span><span class="sr-only">blank</span> she analyzes Renaissance paintings of Umbria, as they can provide accurate representations of fruits that were grown there long ago. </p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"f4db66da-f3f4-44cf-a765-21fef9c83ac4","content":"<p>In sum,</p>"},{"id":"07057966-3018-4f4a-a6ad-7892e2eb5998","content":"<p>Instead,</p>"},{"id":"7c25d6dd-2ec7-4543-886a-7ca8b6972fe7","content":"<p>Thus,</p>"},{"id":"58c4fcbb-2e41-47ba-a178-677156c0f27e","content":"<p>Additionally,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["58c4fcbb-2e41-47ba-a178-677156c0f27e"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;Additionally&rdquo; logically signals that the painting analysis discussed in this sentence is an additional part of the botany research discussed in the previous sentence. That is, to research which fruits Umbrians grew in the past, the botanist analyzes old paintings in addition to looking at old lists of ingredients.&nbsp;</p><p>Choice A is incorrect because &ldquo;in sum&rdquo; illogically signals that the painting analysis discussed in this sentence is a concluding summary of the botany research discussed in the previous sentence. Instead, the painting analysis is an additional part of that research. Choice B is incorrect because &ldquo;instead&rdquo; illogically signals that the painting analysis discussed in this sentence is an alternative to the botany research discussed in the previous sentence. Rather, the painting analysis is an additional part of that research. Choice C is incorrect because &ldquo;thus&rdquo; illogically signals that the painting analysis discussed in this sentence is a result of the botany research discussed in the previous sentence. Instead, the painting analysis is an additional part of that research. </p>$SATQ$, false, 0, $SATQ$OSP-203-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$10c99af2-a9cf-47a6-907a-4670cb9ad6eb$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"39d1a519","external_id":"ca657b0e-f012-43f4-a83e-4ab1fc4e2828","vaultid":"aba47076-5537-4e5f-93cd-aeaef6ba4805","uId":"f61c4a6d-ac74-48f5-a77e-a97fe8510b41","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>To discover which fruit varieties were grown in Italy&rsquo;s Umbria region before the introduction of industrial farming, botanist Isabella Dalla Ragione often turns to centuries-old lists of cooking ingredients. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> she analyzes Renaissance paintings of Umbria, as they can provide accurate representations of fruits that were grown there long ago. </p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"f4db66da-f3f4-44cf-a765-21fef9c83ac4","content":"<p>In sum,</p>"},{"id":"07057966-3018-4f4a-a6ad-7892e2eb5998","content":"<p>Instead,</p>"},{"id":"7c25d6dd-2ec7-4543-886a-7ca8b6972fe7","content":"<p>Thus,</p>"},{"id":"58c4fcbb-2e41-47ba-a178-677156c0f27e","content":"<p>Additionally,</p>"}],"keys":["58c4fcbb-2e41-47ba-a178-677156c0f27e"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;Additionally&rdquo; logically signals that the painting analysis discussed in this sentence is an additional part of the botany research discussed in the previous sentence. That is, to research which fruits Umbrians grew in the past, the botanist analyzes old paintings in addition to looking at old lists of ingredients.&nbsp;</p><p>Choice A is incorrect because &ldquo;in sum&rdquo; illogically signals that the painting analysis discussed in this sentence is a concluding summary of the botany research discussed in the previous sentence. Instead, the painting analysis is an additional part of that research. Choice B is incorrect because &ldquo;instead&rdquo; illogically signals that the painting analysis discussed in this sentence is an alternative to the botany research discussed in the previous sentence. Rather, the painting analysis is an additional part of that research. Choice C is incorrect because &ldquo;thus&rdquo; illogically signals that the painting analysis discussed in this sentence is a result of the botany research discussed in the previous sentence. Instead, the painting analysis is an additional part of that research. </p>","parenttemplatename":"OSP-203-TRA","parenttemplateid":"","templateclusterid":"10c99af2-a9cf-47a6-907a-4670cb9ad6eb","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959325,"updateDate":1691007959325}$SATQ$::jsonb, 1691007959325, 1691007959325),
    ($SATQ$3a715eca$SATQ$, $SATQ$23e256e6-fc68-4151-865c-6bee9f3922b5$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In retrospect, one of the lessons of the 2003 Human Genome Project is that a gene is affected by many factors, not the least of which is its interactions with the protein products of other genes. <span aria-hidden="true">______</span><span class="sr-only">blank</span> rather than just focusing on the human genome, efforts to better understand gene mutations related to disease have begun to consider the human proteome, the complete set of proteins expressed by human genes.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"1cf8cc65-ddad-4d81-948c-ce250d3b4f4b","content":"<p>In other words,</p>"},{"id":"954c8d4c-d525-447c-ae47-5a5ea43eefc1","content":"<p>That said,</p>"},{"id":"23fc0256-08e3-4c00-9229-2675f82a0638","content":"<p>For example,</p>"},{"id":"f50295e6-c781-48b2-a39a-f3cd1a10283a","content":"<p>Accordingly,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["f50295e6-c781-48b2-a39a-f3cd1a10283a"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Accordingly" logically signals that this sentence states a result or consequence of the previous information about the 2003 Human Genome Project. Taking into account an important lesson of the 2003 project (that a gene is affected by interactions with the protein products of other genes), research has begun to consider the human proteome instead of just the genome.</p><p>Choice A is incorrect because "in other words" illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about the 2003 Human Genome Project. Instead, this sentence states a result or consequence of that information. Choice B is incorrect because "that said" illogically signals that the information in this sentence qualifies or contrasts with the previous information about the 2003 Human Genome Project. Instead, this sentence states a result or consequence of that information. Choice C is incorrect because "for example" illogically signals that this sentence provides an example supporting the previous information about the 2003 Human Genome Project. Instead, this sentence states a result or consequence of that information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3a715eca","external_id":"23e256e6-fc68-4151-865c-6bee9f3922b5","vaultid":null,"uId":"7213a85e-f137-4845-bac7-9d407d50f1ab","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In retrospect, one of the lessons of the 2003 Human Genome Project is that a gene is affected by many factors, not the least of which is its interactions with the protein products of other genes. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> rather than just focusing on the human genome, efforts to better understand gene mutations related to disease have begun to consider the human proteome, the complete set of proteins expressed by human genes.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"1cf8cc65-ddad-4d81-948c-ce250d3b4f4b","content":"<p>In other words,</p>"},{"id":"954c8d4c-d525-447c-ae47-5a5ea43eefc1","content":"<p>That said,</p>"},{"id":"23fc0256-08e3-4c00-9229-2675f82a0638","content":"<p>For example,</p>"},{"id":"f50295e6-c781-48b2-a39a-f3cd1a10283a","content":"<p>Accordingly,</p>"}],"keys":["f50295e6-c781-48b2-a39a-f3cd1a10283a"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Accordingly\" logically signals that this sentence states a result or consequence of the previous information about the 2003 Human Genome Project. Taking into account an important lesson of the 2003 project (that a gene is affected by interactions with the protein products of other genes), research has begun to consider the human proteome instead of just the genome.</p><p>Choice A is incorrect because \"in other words\" illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about the 2003 Human Genome Project. Instead, this sentence states a result or consequence of that information. Choice B is incorrect because \"that said\" illogically signals that the information in this sentence qualifies or contrasts with the previous information about the 2003 Human Genome Project. Instead, this sentence states a result or consequence of that information. Choice C is incorrect because \"for example\" illogically signals that this sentence provides an example supporting the previous information about the 2003 Human Genome Project. Instead, this sentence states a result or consequence of that information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323043,"updateDate":1730147323043}$SATQ$::jsonb, 1730147323043, 1730147323043),
    ($SATQ$3b02e88a$SATQ$, $SATQ$459668c5-8725-4aa8-8529-d73621d54e4c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The ancient Arab dhow was a sailing vessel distinguishable by its triangular sails and stitched hull construction.</li>
<li>Dhows were used primarily for trade along the coasts of Arab, South Asian, and East African countries.</li>
<li>Contemporary shipbuilders in Oman use a mix of modern and traditional materials to build replicas of ancient dhows.</li>
<li>Most of the materials used are traditional.</li>
<li>Replica hulls are stitched together using the same traditional coconut palm fiber rope used on the hulls of ancient dhows.&nbsp;</li>
</ul>$SATQ$, $SATQ$<p>The student wants to make a generalization about the materials used in dhow replicas. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"7a17182a-82b2-4cae-b29d-7d372764854e","content":"<p>A traditional material that was used to stitch together the hulls of ancient dhows, coconut palm fiber rope is still used by shipbuilders.&nbsp;</p>"},{"id":"115d919e-fa7f-4386-b295-fd8339f90700","content":"<p>The ancient Arab dhow was a sailing vessel used primarily for trade and distinguishable by its triangular sails.</p>"},{"id":"b29e05fe-310a-4d29-9e75-784dd1f8c90d","content":"<p>Although most materials used in dhow replicas are traditional, some modern materials are used.</p>"},{"id":"399d0850-d2a2-4d83-9e12-2098e446d27b","content":"<p>Contemporary shipbuilders in Oman build replicas of the dhow, which was an ancient sailing vessel with a stitched hull construction.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b29e05fe-310a-4d29-9e75-784dd1f8c90d"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence makes a generalization about the materials used in dhow replicas, noting that while some modern materials are used, most of the materials are traditional.</p><p>Choice A is incorrect. The sentence provides an example of a traditional material used in ancient dhows; it doesn&rsquo;t indicate that the material is used in dhow replicas or make any other generalization about materials used in those replicas. Choice B is incorrect. The sentence explains what an ancient dhow was; it doesn&rsquo;t make a generalization about materials used to make dhow replicas. Choice D is incorrect. The sentence introduces the construction of dhow replicas to an audience unfamiliar with the vessel; it doesn&rsquo;t make a generalization about the materials used in those replicas.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3b02e88a","external_id":"459668c5-8725-4aa8-8529-d73621d54e4c","vaultid":null,"uId":"3127f300-baf5-42e4-b6c9-cb8cafe4415d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The ancient Arab dhow was a sailing vessel distinguishable by its triangular sails and stitched hull construction.</li>\n<li>Dhows were used primarily for trade along the coasts of Arab, South Asian, and East African countries.</li>\n<li>Contemporary shipbuilders in Oman use a mix of modern and traditional materials to build replicas of ancient dhows.</li>\n<li>Most of the materials used are traditional.</li>\n<li>Replica hulls are stitched together using the same traditional coconut palm fiber rope used on the hulls of ancient dhows.&nbsp;</li>\n</ul>","stem":"<p>The student wants to make a generalization about the materials used in dhow replicas. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"7a17182a-82b2-4cae-b29d-7d372764854e","content":"<p>A traditional material that was used to stitch together the hulls of ancient dhows, coconut palm fiber rope is still used by shipbuilders.&nbsp;</p>"},{"id":"115d919e-fa7f-4386-b295-fd8339f90700","content":"<p>The ancient Arab dhow was a sailing vessel used primarily for trade and distinguishable by its triangular sails.</p>"},{"id":"b29e05fe-310a-4d29-9e75-784dd1f8c90d","content":"<p>Although most materials used in dhow replicas are traditional, some modern materials are used.</p>"},{"id":"399d0850-d2a2-4d83-9e12-2098e446d27b","content":"<p>Contemporary shipbuilders in Oman build replicas of the dhow, which was an ancient sailing vessel with a stitched hull construction.</p>"}],"keys":["b29e05fe-310a-4d29-9e75-784dd1f8c90d"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence makes a generalization about the materials used in dhow replicas, noting that while some modern materials are used, most of the materials are traditional.</p><p>Choice A is incorrect. The sentence provides an example of a traditional material used in ancient dhows; it doesn&rsquo;t indicate that the material is used in dhow replicas or make any other generalization about materials used in those replicas. Choice B is incorrect. The sentence explains what an ancient dhow was; it doesn&rsquo;t make a generalization about materials used to make dhow replicas. Choice D is incorrect. The sentence introduces the construction of dhow replicas to an audience unfamiliar with the vessel; it doesn&rsquo;t make a generalization about the materials used in those replicas.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323034,"updateDate":1730147323034}$SATQ$::jsonb, 1730147323034, 1730147323034),
    ($SATQ$3c925481$SATQ$, $SATQ$6145c3c8-0703-402a-82a4-b54f1769dd3c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Pineapple is a fruit that contains ascorbic acid, an essential nutrient for humans.</li>
<li>Every 100 grams (g) of pineapple contains 48 milligrams (mg) of ascorbic acid.</li>
<li>Many animals can make ascorbic acid in their bodies, but humans cannot.</li>
<li>Humans must get ascorbic acid from foods, including fruits and vegetables.</li>
<li>Ascorbic acid is also known as vitamin C.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to provide an example of a fruit that contains vitamin C. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"8d17452b-3262-4856-b3ba-5a7d71894d09","content":"<p>Humans cannot make ascorbic acid in their bodies, but they can get it from foods, such as fruits, for example.</p>"},{"id":"34d535f9-8e97-494c-9ff5-b25dedc285e0","content":"<p>Vitamin C, also known as ascorbic acid, can be found in pineapple as well as other fruits.</p>"},{"id":"270e1af2-fdbc-40ed-b211-b4b4a62c6472","content":"<p>Since humans cannot make vitamin C in their bodies, they must get it from food.</p>"},{"id":"72465b5c-4b61-4387-bfd0-2bf7f489bbba","content":"<p>Many animals can make ascorbic acid, which is also known as vitamin C, in their bodies, but humans cannot.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["34d535f9-8e97-494c-9ff5-b25dedc285e0"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence provides an example of a fruit that contains vitamin C, noting that vitamin C (also known as ascorbic acid) can be found in pineapple as well as other fruits.</p><p>Choice A is incorrect. While the sentence does explain that humans can get vitamin C from fruits, it doesn&rsquo;t provide an example of a specific fruit that contains vitamin C. Choice C is incorrect. The sentence explains why humans must get vitamin C from foods; it doesn&rsquo;t provide an example of a fruit that contains vitamin C. Choice D is incorrect. The sentence compares vitamin C production in animals with vitamin C production in humans; it doesn&rsquo;t provide an example of a fruit that contains vitamin C.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3c925481","external_id":"6145c3c8-0703-402a-82a4-b54f1769dd3c","vaultid":null,"uId":"8ca4e149-7a76-4716-9f4f-3312dd72be0a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Pineapple is a fruit that contains ascorbic acid, an essential nutrient for humans.</li>\n<li>Every 100 grams (g) of pineapple contains 48 milligrams (mg) of ascorbic acid.</li>\n<li>Many animals can make ascorbic acid in their bodies, but humans cannot.</li>\n<li>Humans must get ascorbic acid from foods, including fruits and vegetables.</li>\n<li>Ascorbic acid is also known as vitamin C.</li>\n</ul>","stem":"<p>The student wants to provide an example of a fruit that contains vitamin C. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"8d17452b-3262-4856-b3ba-5a7d71894d09","content":"<p>Humans cannot make ascorbic acid in their bodies, but they can get it from foods, such as fruits, for example.</p>"},{"id":"34d535f9-8e97-494c-9ff5-b25dedc285e0","content":"<p>Vitamin C, also known as ascorbic acid, can be found in pineapple as well as other fruits.</p>"},{"id":"270e1af2-fdbc-40ed-b211-b4b4a62c6472","content":"<p>Since humans cannot make vitamin C in their bodies, they must get it from food.</p>"},{"id":"72465b5c-4b61-4387-bfd0-2bf7f489bbba","content":"<p>Many animals can make ascorbic acid, which is also known as vitamin C, in their bodies, but humans cannot.&nbsp;</p>"}],"keys":["34d535f9-8e97-494c-9ff5-b25dedc285e0"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence provides an example of a fruit that contains vitamin C, noting that vitamin C (also known as ascorbic acid) can be found in pineapple as well as other fruits.</p><p>Choice A is incorrect. While the sentence does explain that humans can get vitamin C from fruits, it doesn&rsquo;t provide an example of a specific fruit that contains vitamin C. Choice C is incorrect. The sentence explains why humans must get vitamin C from foods; it doesn&rsquo;t provide an example of a fruit that contains vitamin C. Choice D is incorrect. The sentence compares vitamin C production in animals with vitamin C production in humans; it doesn&rsquo;t provide an example of a fruit that contains vitamin C.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061177,"updateDate":1755117061177}$SATQ$::jsonb, 1755117061177, 1755117061177),
    ($SATQ$3dcc7140$SATQ$, $SATQ$737599e7-dea7-4978-87c8-0ddf52eecc44$SATQ$::uuid, $SATQ$d6df4072-6313-4fb6-b34a-f2efde76aba9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Nissologists are scientists who study islands.</li>
<li>Some nissologists define an island as any piece of land surrounded by water.</li>
<li>Using that definition, they determined that Sweden has 221,000 islands.</li>
<li>Other nissologists define an island as being 1 kilometer square, a certain distance from the mainland, and having at least 50 permanent residents.</li>
<li>Using that definition, they determined that Sweden has 24 islands.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to make and support a generalization about nissologists&rsquo; definition of an island. Which choice most effectively uses relevant information from the notes to accomplish these goals?</p>$SATQ$, $SATQ$[{"id":"c0db40a8-058f-459d-989e-d3933539c9a6","content":"<p>The definition of an island as any piece of land surrounded by water is supported by some nissologists, scientists who study islands.</p>"},{"id":"edf25450-ddc1-4daf-a5fa-f231ac2debdb","content":"<p>Multiple counts of Sweden&rsquo;s islands have been based on different definitions of an island.</p>"},{"id":"5ce569fd-5b9f-4816-bbd1-8d2d07152a79","content":"<p>Based on a recent count, Sweden has a relatively small number of islands with at least 50 permanent residents.</p>"},{"id":"716b574f-13e4-47fc-94b0-681f7b7f81d6","content":"<p>Nissologists&rsquo; different definitions can result in huge disparities in counts of islands, as the example of Sweden shows.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["716b574f-13e4-47fc-94b0-681f7b7f81d6"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence makes a generalization about nissologists&rsquo; definition of an island&mdash;specifically, that the use of one definition rather than another can result in huge disparities in the number of islands counted&mdash;and supports that generalization by citing Sweden as an example. </p><p>Choice A is incorrect. The sentence introduces one definition of an island to an audience unfamiliar with nissologists; it doesn&rsquo;t make a generalization about nissologists&rsquo; definition of an island.&nbsp;Choice B is incorrect. While the sentence synthesizes information from the notes about counts of Sweden&rsquo;s islands, it doesn&rsquo;t make and support a generalization about nissologists&rsquo; definition of an island. Choice C is incorrect. The sentence makes an inference about islands in Sweden; it doesn&rsquo;t mention nissologists&rsquo; definition of an island or make a generalization about it.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-747-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$da073384-7eaa-4c58-bbf8-9b2890f858e9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3dcc7140","external_id":"737599e7-dea7-4978-87c8-0ddf52eecc44","vaultid":"d6df4072-6313-4fb6-b34a-f2efde76aba9","uId":"954d555d-e9de-4e62-8235-2a62ed4b44d7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Nissologists are scientists who study islands.</li>\n<li>Some nissologists define an island as any piece of land surrounded by water.</li>\n<li>Using that definition, they determined that Sweden has 221,000 islands.</li>\n<li>Other nissologists define an island as being 1 kilometer square, a certain distance from the mainland, and having at least 50 permanent residents.</li>\n<li>Using that definition, they determined that Sweden has 24 islands.</li>\n</ul>","stem":"<p>The student wants to make and support a generalization about nissologists&rsquo; definition of an island. Which choice most effectively uses relevant information from the notes to accomplish these goals?</p>","answerOptions":[{"id":"c0db40a8-058f-459d-989e-d3933539c9a6","content":"<p>The definition of an island as any piece of land surrounded by water is supported by some nissologists, scientists who study islands.</p>"},{"id":"edf25450-ddc1-4daf-a5fa-f231ac2debdb","content":"<p>Multiple counts of Sweden&rsquo;s islands have been based on different definitions of an island.</p>"},{"id":"5ce569fd-5b9f-4816-bbd1-8d2d07152a79","content":"<p>Based on a recent count, Sweden has a relatively small number of islands with at least 50 permanent residents.</p>"},{"id":"716b574f-13e4-47fc-94b0-681f7b7f81d6","content":"<p>Nissologists&rsquo; different definitions can result in huge disparities in counts of islands, as the example of Sweden shows.</p>"}],"keys":["716b574f-13e4-47fc-94b0-681f7b7f81d6"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence makes a generalization about nissologists&rsquo; definition of an island&mdash;specifically, that the use of one definition rather than another can result in huge disparities in the number of islands counted&mdash;and supports that generalization by citing Sweden as an example. </p><p>Choice A is incorrect. The sentence introduces one definition of an island to an audience unfamiliar with nissologists; it doesn&rsquo;t make a generalization about nissologists&rsquo; definition of an island.&nbsp;Choice B is incorrect. While the sentence synthesizes information from the notes about counts of Sweden&rsquo;s islands, it doesn&rsquo;t make and support a generalization about nissologists&rsquo; definition of an island. Choice C is incorrect. The sentence makes an inference about islands in Sweden; it doesn&rsquo;t mention nissologists&rsquo; definition of an island or make a generalization about it.&nbsp;</p>","parenttemplatename":"OSP-747-SYN","parenttemplateid":"","templateclusterid":"da073384-7eaa-4c58-bbf8-9b2890f858e9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959350,"updateDate":1691007959350}$SATQ$::jsonb, 1691007959350, 1691007959350),
    ($SATQ$3ea7372e$SATQ$, $SATQ$ce15dc57-2b8e-4b3c-b7b4-11d18f0ae2e0$SATQ$::uuid, $SATQ$8513564e-08ed-4f50-95c3-79e76aaccf6e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>In the art world, the term biennial traditionally refers to an art exhibition that takes place every two years in a single location.</li>
<li>Such biennials are held in New York, Berlin, and Venice.</li>
<li>In 2006, artists Ed Gomez and Luis Hernandez founded the unconventional MexiCali Biennial.</li>
<li>The MexiCali Biennial hosts exhibitions in different venues on both sides of the US-Mexico border.</li>
<li>The MexiCali Biennial has taken place on an uneven schedule, with exhibitions in 2006, 2009&ndash;10, 2013, and 2018&ndash;20.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a difference between the MexiCali Biennial and traditional biennials.&nbsp;Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"9f6fc752-fb78-4263-842e-fdf5eec18e4f","content":"<p>In 2006, artists Ed Gomez and Luis Hernandez founded the MexiCali Biennial, which has taken place in 2006, 2009&ndash;10, 2013, and 2018&ndash;20.</p>"},{"id":"5f0dbc87-0874-4f6f-9237-92d985db4ae0","content":"<p>Unlike traditional biennials, the MexiCali Biennial hosts exhibitions in different venues on an uneven schedule.</p>"},{"id":"7b117f21-358f-4f99-a3a0-d74a067db3df","content":"<p>The term biennial traditionally refers to an art exhibition that takes place every two years in a single location, not to exhibitions hosted at a variety of times and venues.</p>"},{"id":"6642dfc3-53a4-44b4-b6bb-3ac8e229835d","content":"<p>Biennial exhibitions have been held in New York, Berlin, and Venice but also on both sides of the US-Mexico border.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["5f0dbc87-0874-4f6f-9237-92d985db4ae0"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence effectively emphasizes a difference between the MexiCali Biennial and traditional biennials, stating that the MexiCali Biennial is unlike traditional biennials because it hosts exhibitions in different venues on an uneven schedule. </p><p>Choice A is incorrect. The sentence indicates who founded the MexiCali Biennial and the years this biennial has taken place; it doesn&rsquo;t emphasize a difference between the MexiCali Biennial and traditional biennials. Choice C is incorrect. While the sentence clarifies the traditional meaning of biennial with language that could apply to the MexiCali Biennial, it doesn&rsquo;t mention the MexiCali Biennial by name. Therefore, the sentence doesn&rsquo;t effectively emphasize a difference between the MexiCali Biennial and traditional biennials. Choice D is incorrect. The sentence notes locations where various biennial exhibitions have been held; it doesn&rsquo;t emphasize a difference between the MexiCali Biennial and traditional biennials. </p>$SATQ$, false, 0, $SATQ$OSP-789-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$5989a578-d9e2-4c83-9f99-b2e279dbfa44$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3ea7372e","external_id":"ce15dc57-2b8e-4b3c-b7b4-11d18f0ae2e0","vaultid":"8513564e-08ed-4f50-95c3-79e76aaccf6e","uId":"bb473624-2450-4481-8daa-3f8ee26aa4f7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>In the art world, the term biennial traditionally refers to an art exhibition that takes place every two years in a single location.</li>\n<li>Such biennials are held in New York, Berlin, and Venice.</li>\n<li>In 2006, artists Ed Gomez and Luis Hernandez founded the unconventional MexiCali Biennial.</li>\n<li>The MexiCali Biennial hosts exhibitions in different venues on both sides of the US-Mexico border.</li>\n<li>The MexiCali Biennial has taken place on an uneven schedule, with exhibitions in 2006, 2009&ndash;10, 2013, and 2018&ndash;20.</li>\n</ul>","stem":"<p>The student wants to emphasize a difference between the MexiCali Biennial and traditional biennials.&nbsp;Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"9f6fc752-fb78-4263-842e-fdf5eec18e4f","content":"<p>In 2006, artists Ed Gomez and Luis Hernandez founded the MexiCali Biennial, which has taken place in 2006, 2009&ndash;10, 2013, and 2018&ndash;20.</p>"},{"id":"5f0dbc87-0874-4f6f-9237-92d985db4ae0","content":"<p>Unlike traditional biennials, the MexiCali Biennial hosts exhibitions in different venues on an uneven schedule.</p>"},{"id":"7b117f21-358f-4f99-a3a0-d74a067db3df","content":"<p>The term biennial traditionally refers to an art exhibition that takes place every two years in a single location, not to exhibitions hosted at a variety of times and venues.</p>"},{"id":"6642dfc3-53a4-44b4-b6bb-3ac8e229835d","content":"<p>Biennial exhibitions have been held in New York, Berlin, and Venice but also on both sides of the US-Mexico border.</p>"}],"keys":["5f0dbc87-0874-4f6f-9237-92d985db4ae0"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence effectively emphasizes a difference between the MexiCali Biennial and traditional biennials, stating that the MexiCali Biennial is unlike traditional biennials because it hosts exhibitions in different venues on an uneven schedule. </p><p>Choice A is incorrect. The sentence indicates who founded the MexiCali Biennial and the years this biennial has taken place; it doesn&rsquo;t emphasize a difference between the MexiCali Biennial and traditional biennials. Choice C is incorrect. While the sentence clarifies the traditional meaning of biennial with language that could apply to the MexiCali Biennial, it doesn&rsquo;t mention the MexiCali Biennial by name. Therefore, the sentence doesn&rsquo;t effectively emphasize a difference between the MexiCali Biennial and traditional biennials. Choice D is incorrect. The sentence notes locations where various biennial exhibitions have been held; it doesn&rsquo;t emphasize a difference between the MexiCali Biennial and traditional biennials. </p>","parenttemplatename":"OSP-789-SYN","parenttemplateid":"","templateclusterid":"5989a578-d9e2-4c83-9f99-b2e279dbfa44","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959353,"updateDate":1691007959353}$SATQ$::jsonb, 1691007959353, 1691007959353),
    ($SATQ$3fa48bf3$SATQ$, $SATQ$69bb5669-cf08-40db-a385-8a5074a1920c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>British scholar Robert Plot described fossilized dinosaur bones in his 1676 book <em>The Natural History of Oxfordshire.</em></li>
<li>Plot earned a reputation for being the first person to have discovered dinosaur remains.</li>
<li>In 1990, archaeologists in Lesotho, in southern Africa, discovered a fossilized phalanx of a <em>Massospondylus carinatus</em> dinosaur in a cave once inhabited by humans.</li>
<li>Indigenous Khoesan and Basotho peoples had inhabited the cave beginning around 1100 CE.</li>
<li>According to paleontologist Julien Benoit, these peoples may have found the phalanx and brought it to the cave centuries before Plot&rsquo;s descriptions.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the significance of the 1990 discovery to Plot&rsquo;s reputation. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"48776f7e-a620-4bae-a5af-8b0b55323f2a","content":"<p>Benoit challenged Plot&rsquo;s reputation for being the first person to have discovered <em>M. carinatus</em> remains.</p>"},{"id":"557fa2fc-ffd9-46b0-a28f-3ac201e56e05","content":"<p>Evidence that Khoesan and Basotho peoples may have found an <em>M. carinatus</em> phalanx as long ago as 1100 CE suggests that Plot may not have been the first person to have discovered dinosaur remains.</p>"},{"id":"a2a70794-d52d-45a4-8a25-e8879408e801","content":"<p>According to Benoit&rsquo;s analysis of the 1990 discovery, Indigenous peoples in southern Africa may have brought the fossilized phalanx to the cave as long ago as 1100 CE.</p>"},{"id":"993c793c-616f-4a8a-930b-f7295124125e","content":"<p>In 1990, more than three centuries after Plot claimed in his book that he had found fossilized dinosaur bones, archaeologists uncovered evidence in southern Africa that disproved his claims. &nbsp;&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["557fa2fc-ffd9-46b0-a28f-3ac201e56e05"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. Noting that the evidence suggests Indigenous peoples may have found dinosaur remains in 1100 CE, the sentence emphasizes how the 1990 discovery challenged Plot&rsquo;s reputation as the first person to discover dinosaur remains.</p><p>Choice A is incorrect. While the sentence does emphasize that Benoit challenged Plot&rsquo;s reputation, it
misrepresents information in the notes; Plot was reputed to be the first person to discover dinosaur remains in general, not the first person to discover <em>M. carinatus</em> remains specifically. Choice C is incorrect. The sentence only partially explains the significance of the 1990 discovery, noting that it suggests Indigenous people brought dinosaur remains to the cave in 1100 CE; it doesn&rsquo;t explain the discovery&rsquo;s significance to Plot&rsquo;s reputation. Choice D is incorrect. While the sentence does emphasize that the discovery challenged Plot&rsquo;s reputation, it misrepresents information in the notes. The notes don&rsquo;t indicate that the 1990 discovery cast any doubt on Plot&rsquo;s claims to have found fossilized dinosaur bones; rather, the discovery challenged Plot&rsquo;s reputation for being the first to discover dinosaur bones.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3fa48bf3","external_id":"69bb5669-cf08-40db-a385-8a5074a1920c","vaultid":null,"uId":"29f14239-ea01-48ad-ac7b-336f0d5bdf75","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>British scholar Robert Plot described fossilized dinosaur bones in his 1676 book <em>The Natural History of Oxfordshire.</em></li>\n<li>Plot earned a reputation for being the first person to have discovered dinosaur remains.</li>\n<li>In 1990, archaeologists in Lesotho, in southern Africa, discovered a fossilized phalanx of a <em>Massospondylus carinatus</em> dinosaur in a cave once inhabited by humans.</li>\n<li>Indigenous Khoesan and Basotho peoples had inhabited the cave beginning around 1100 CE.</li>\n<li>According to paleontologist Julien Benoit, these peoples may have found the phalanx and brought it to the cave centuries before Plot&rsquo;s descriptions.</li>\n</ul>","stem":"<p>The student wants to emphasize the significance of the 1990 discovery to Plot&rsquo;s reputation. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"48776f7e-a620-4bae-a5af-8b0b55323f2a","content":"<p>Benoit challenged Plot&rsquo;s reputation for being the first person to have discovered <em>M. carinatus</em> remains.</p>"},{"id":"557fa2fc-ffd9-46b0-a28f-3ac201e56e05","content":"<p>Evidence that Khoesan and Basotho peoples may have found an <em>M. carinatus</em> phalanx as long ago as 1100 CE suggests that Plot may not have been the first person to have discovered dinosaur remains.</p>"},{"id":"a2a70794-d52d-45a4-8a25-e8879408e801","content":"<p>According to Benoit&rsquo;s analysis of the 1990 discovery, Indigenous peoples in southern Africa may have brought the fossilized phalanx to the cave as long ago as 1100 CE.</p>"},{"id":"993c793c-616f-4a8a-930b-f7295124125e","content":"<p>In 1990, more than three centuries after Plot claimed in his book that he had found fossilized dinosaur bones, archaeologists uncovered evidence in southern Africa that disproved his claims. &nbsp;&nbsp;</p>"}],"keys":["557fa2fc-ffd9-46b0-a28f-3ac201e56e05"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. Noting that the evidence suggests Indigenous peoples may have found dinosaur remains in 1100 CE, the sentence emphasizes how the 1990 discovery challenged Plot&rsquo;s reputation as the first person to discover dinosaur remains.</p><p>Choice A is incorrect. While the sentence does emphasize that Benoit challenged Plot&rsquo;s reputation, it\nmisrepresents information in the notes; Plot was reputed to be the first person to discover dinosaur remains in general, not the first person to discover <em>M. carinatus</em> remains specifically. Choice C is incorrect. The sentence only partially explains the significance of the 1990 discovery, noting that it suggests Indigenous people brought dinosaur remains to the cave in 1100 CE; it doesn&rsquo;t explain the discovery&rsquo;s significance to Plot&rsquo;s reputation. Choice D is incorrect. While the sentence does emphasize that the discovery challenged Plot&rsquo;s reputation, it misrepresents information in the notes. The notes don&rsquo;t indicate that the 1990 discovery cast any doubt on Plot&rsquo;s claims to have found fossilized dinosaur bones; rather, the discovery challenged Plot&rsquo;s reputation for being the first to discover dinosaur bones.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061178,"updateDate":1755117061178}$SATQ$::jsonb, 1755117061178, 1755117061178),
    ($SATQ$3fd0ab63$SATQ$, $SATQ$c230d1ab-a96e-40cb-9ea1-c96e562a19d9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Voting members of the 2002 Latin Grammys were impressed by Banda Cuisillos&rsquo;s album <em>Puras Rancheras Con Cuisillos</em> and its contribution to the banda genre, a form of regional Mexican music featuring large ensembles of wind instruments and drums that first developed in southern and central Mexico in the mid-nineteenth century. <span aria-hidden="true">______</span><span class="sr-only">blank</span> they awarded the group the Best Banda Album award.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"e43a0cc8-612c-447d-bf99-4370d11b129e","content":"<p>In contrast,</p>"},{"id":"68f67758-2642-4978-b83d-1925908e308f","content":"<p>Meanwhile,</p>"},{"id":"a8d61086-f0b2-470c-8c3c-ff3598155007","content":"<p>Nevertheless,</p>"},{"id":"27d0e41d-7a25-47ef-a501-7350671ba53f","content":"<p>Accordingly,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["27d0e41d-7a25-47ef-a501-7350671ba53f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Accordingly" logically signals that the information in this sentence&mdash;that the voting members awarded Banda Cuisillos the Best Banda Album award&mdash;is in accordance with, or results from, the previous information about the voters being impressed by Banda Cuisillos&rsquo;s album.</p><p>Choice A is incorrect because "in contrast" illogically signals that the information in this sentence contrasts with the previous information about voting members being impressed by Banda Cuisillos&rsquo;s album. Instead, the voters&rsquo; decision to give the group the Best Banda Album award is in accordance with, or results from, that information. Choice B is incorrect because "meanwhile" illogically signals that the information in this sentence is separate from (while occurring simultaneously with) the previous information about the voting members being impressed by Banda Cuisillos&rsquo;s album. Instead, the voters&rsquo; decision to give the group the Best Banda Album award is in accordance with, or results from, that information. Choice C is incorrect because "nevertheless" illogically signals that the information that follows is despite the information about the voting members being impressed by Banda Cuisillos&rsquo;s album. Instead, the voters&rsquo; decision to give the group the Best Banda Album award is in accordance with, or results from, that information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3fd0ab63","external_id":"c230d1ab-a96e-40cb-9ea1-c96e562a19d9","vaultid":null,"uId":"3a736a9f-2d8e-4513-88af-6c7c73499070","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Voting members of the 2002 Latin Grammys were impressed by Banda Cuisillos&rsquo;s album <em>Puras Rancheras Con Cuisillos</em> and its contribution to the banda genre, a form of regional Mexican music featuring large ensembles of wind instruments and drums that first developed in southern and central Mexico in the mid-nineteenth century. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> they awarded the group the Best Banda Album award.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"e43a0cc8-612c-447d-bf99-4370d11b129e","content":"<p>In contrast,</p>"},{"id":"68f67758-2642-4978-b83d-1925908e308f","content":"<p>Meanwhile,</p>"},{"id":"a8d61086-f0b2-470c-8c3c-ff3598155007","content":"<p>Nevertheless,</p>"},{"id":"27d0e41d-7a25-47ef-a501-7350671ba53f","content":"<p>Accordingly,</p>"}],"keys":["27d0e41d-7a25-47ef-a501-7350671ba53f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Accordingly\" logically signals that the information in this sentence&mdash;that the voting members awarded Banda Cuisillos the Best Banda Album award&mdash;is in accordance with, or results from, the previous information about the voters being impressed by Banda Cuisillos&rsquo;s album.</p><p>Choice A is incorrect because \"in contrast\" illogically signals that the information in this sentence contrasts with the previous information about voting members being impressed by Banda Cuisillos&rsquo;s album. Instead, the voters&rsquo; decision to give the group the Best Banda Album award is in accordance with, or results from, that information. Choice B is incorrect because \"meanwhile\" illogically signals that the information in this sentence is separate from (while occurring simultaneously with) the previous information about the voting members being impressed by Banda Cuisillos&rsquo;s album. Instead, the voters&rsquo; decision to give the group the Best Banda Album award is in accordance with, or results from, that information. Choice C is incorrect because \"nevertheless\" illogically signals that the information that follows is despite the information about the voting members being impressed by Banda Cuisillos&rsquo;s album. Instead, the voters&rsquo; decision to give the group the Best Banda Album award is in accordance with, or results from, that information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$4105f5ac$SATQ$, $SATQ$293b55b8-49d6-42e6-b03d-5f4ecc052dc3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>When, in 2017, Cambridge University students Lucy Moss and Toby Marlow decided they wanted to develop a musical together, one of their goals was for their female actor friends to have good parts to play. <span aria-hidden="true">______</span><span class="sr-only">blank</span> they created the show <em>Six</em>, a retelling of the history of King Henry VIII&rsquo;s wives in which each of the six queens has a starring role.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"08f04e40-f5c7-4a12-8f04-79fbdf08b23f","content":"<p>In other words,</p>"},{"id":"ebdc3d78-662a-4f75-b5cd-895b2025f053","content":"<p>In summary,</p>"},{"id":"774c418d-2602-40c8-9f99-3b607f3c506c","content":"<p>For example,</p>"},{"id":"c29dce27-3b9f-49c4-bf95-fe3f7837ff5b","content":"<p>To that end,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["c29dce27-3b9f-49c4-bf95-fe3f7837ff5b"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "To that end" logically signals that the information in this sentence&mdash;the students&rsquo; creation of a show with six starring female roles&mdash;is the product of a goal or desire in the previous sentence (the students&rsquo; wish to develop a musical with roles for female actors).</p><p>Choice A is incorrect because "in other words" illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about the students&rsquo; wish to develop a musical with roles for female actors. Instead, the students&rsquo; show is the product of that desire. Choice B is incorrect because "in summary" illogically signals that the information in this sentence summarizes the previous information about the students&rsquo; wish to develop a musical with roles for female actors. Instead, the students&rsquo; show is the product of that desire. Choice C is incorrect because "for example" illogically signals that the information in this sentence is merely an example of the previous information about the students&rsquo; wish to develop a musical with roles for female actors. Instead, the students&rsquo; show is the direct product of that desire.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4105f5ac","external_id":"293b55b8-49d6-42e6-b03d-5f4ecc052dc3","vaultid":null,"uId":"7b4ddcd4-5ca0-4383-b8a0-f5c316dcb92c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>When, in 2017, Cambridge University students Lucy Moss and Toby Marlow decided they wanted to develop a musical together, one of their goals was for their female actor friends to have good parts to play. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> they created the show <em>Six</em>, a retelling of the history of King Henry VIII&rsquo;s wives in which each of the six queens has a starring role.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"08f04e40-f5c7-4a12-8f04-79fbdf08b23f","content":"<p>In other words,</p>"},{"id":"ebdc3d78-662a-4f75-b5cd-895b2025f053","content":"<p>In summary,</p>"},{"id":"774c418d-2602-40c8-9f99-3b607f3c506c","content":"<p>For example,</p>"},{"id":"c29dce27-3b9f-49c4-bf95-fe3f7837ff5b","content":"<p>To that end,</p>"}],"keys":["c29dce27-3b9f-49c4-bf95-fe3f7837ff5b"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"To that end\" logically signals that the information in this sentence&mdash;the students&rsquo; creation of a show with six starring female roles&mdash;is the product of a goal or desire in the previous sentence (the students&rsquo; wish to develop a musical with roles for female actors).</p><p>Choice A is incorrect because \"in other words\" illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about the students&rsquo; wish to develop a musical with roles for female actors. Instead, the students&rsquo; show is the product of that desire. Choice B is incorrect because \"in summary\" illogically signals that the information in this sentence summarizes the previous information about the students&rsquo; wish to develop a musical with roles for female actors. Instead, the students&rsquo; show is the product of that desire. Choice C is incorrect because \"for example\" illogically signals that the information in this sentence is merely an example of the previous information about the students&rsquo; wish to develop a musical with roles for female actors. Instead, the students&rsquo; show is the direct product of that desire.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669204,"updateDate":1743430669204}$SATQ$::jsonb, 1743430669204, 1743430669204),
    ($SATQ$4154a7a3$SATQ$, $SATQ$0f5bfa92-30e4-40c4-a83a-c4457a854ece$SATQ$::uuid, $SATQ$3eb5f84b-7d4a-4ead-9efc-9fd6b5685d34$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 1891, dancer and choreographer Loie Fuller first performed her celebrated Serpentine Dance, artfully twirling her long, flowing skirt to create striking visual effects. <span aria-hidden="true">______</span><span class="sr-only">blank</span> in 1896, cinema pioneers Auguste and Louis Lumi&egrave;re made a groundbreaking short film of Fuller&rsquo;s dance.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"f2abbc65-00a3-4a1a-bbb1-1ff4aa01a752","content":"<p>However,</p>"},{"id":"e408f4cb-7cad-416d-b52d-07fb9b82c339","content":"<p>In conclusion,</p>"},{"id":"322846f3-ffe4-4eb9-81cf-28bdc9c74861","content":"<p>Later,</p>"},{"id":"ce5013ac-6784-4c74-bdab-1691e6645429","content":"<p>In other words,&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["322846f3-ffe4-4eb9-81cf-28bdc9c74861"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;Later&rdquo; logically signals that the event discussed in this sentence&mdash;the creation of the short film featuring Fuller&rsquo;s dance&mdash;is a related event that occurred after the event discussed in the previous sentence (the 1891 debut of the dance). </p><p>Choice A is incorrect because &ldquo;however&rdquo; illogically signals that the information in this sentence contrasts with the information in the previous sentence. Instead, the creation of the short film is a related event that followed the event discussed in the previous sentence. Choice B is incorrect because &ldquo;in conclusion&rdquo; illogically signals that the information in this sentence concludes or summarizes the information in the previous sentence. Instead, the creation of the short film is a related event that followed the event discussed in the previous sentence. Choice D is incorrect because &ldquo;in other words&rdquo; illogically signals that the information in this sentence is a paraphrase or restatement of the information in the previous sentence. Instead, the creation of the short film is a related event that followed the event discussed in the previous sentence. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-E005$SATQ$, $SATQ$$SATQ$, $SATQ$90926b6c-78af-47e3-8e9c-6a293e876446$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4154a7a3","external_id":"0f5bfa92-30e4-40c4-a83a-c4457a854ece","vaultid":"3eb5f84b-7d4a-4ead-9efc-9fd6b5685d34","uId":"eb470840-e8f6-47c4-8a11-e4ed8d242e47","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 1891, dancer and choreographer Loie Fuller first performed her celebrated Serpentine Dance, artfully twirling her long, flowing skirt to create striking visual effects. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in 1896, cinema pioneers Auguste and Louis Lumi&egrave;re made a groundbreaking short film of Fuller&rsquo;s dance.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"f2abbc65-00a3-4a1a-bbb1-1ff4aa01a752","content":"<p>However,</p>"},{"id":"e408f4cb-7cad-416d-b52d-07fb9b82c339","content":"<p>In conclusion,</p>"},{"id":"322846f3-ffe4-4eb9-81cf-28bdc9c74861","content":"<p>Later,</p>"},{"id":"ce5013ac-6784-4c74-bdab-1691e6645429","content":"<p>In other words,&nbsp;</p>"}],"keys":["322846f3-ffe4-4eb9-81cf-28bdc9c74861"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;Later&rdquo; logically signals that the event discussed in this sentence&mdash;the creation of the short film featuring Fuller&rsquo;s dance&mdash;is a related event that occurred after the event discussed in the previous sentence (the 1891 debut of the dance). </p><p>Choice A is incorrect because &ldquo;however&rdquo; illogically signals that the information in this sentence contrasts with the information in the previous sentence. Instead, the creation of the short film is a related event that followed the event discussed in the previous sentence. Choice B is incorrect because &ldquo;in conclusion&rdquo; illogically signals that the information in this sentence concludes or summarizes the information in the previous sentence. Instead, the creation of the short film is a related event that followed the event discussed in the previous sentence. Choice D is incorrect because &ldquo;in other words&rdquo; illogically signals that the information in this sentence is a paraphrase or restatement of the information in the previous sentence. Instead, the creation of the short film is a related event that followed the event discussed in the previous sentence. </p>","parenttemplatename":"OSP-KA-TRA-E005","parenttemplateid":"","templateclusterid":"90926b6c-78af-47e3-8e9c-6a293e876446","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$420dea42$SATQ$, $SATQ$29b663d7-ec23-47a6-9d1a-86a57df1e896$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>A blend of gabardine and wool, the material for Elvis Presley&rsquo;s Gold Vine jumpsuit was flexible enough to allow the singer to perform his signature dance moves. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the added weight of the suit&rsquo;s swirling vines made of gold rhinestones likely limited Elvis&rsquo;s mobility to some degree.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"73b23dc4-cce6-4d00-809d-5bcea08f935a","content":"<p>For this reason,</p>"},{"id":"a74586c6-175b-4bfc-bfd7-765952d37c7b","content":"<p>Firstly,</p>"},{"id":"07f6bfac-5d5e-47c9-b4bb-649a59abe322","content":"<p>However,</p>"},{"id":"eb21f0ee-3a3c-40e3-b48a-20a0e9164d22","content":"<p>In other words,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["07f6bfac-5d5e-47c9-b4bb-649a59abe322"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "However" logically signals that the claim in this sentence&mdash;that the weight of the gold rhinestones likely limited Elvis&rsquo;s mobility&mdash;contrasts with the previous information about the material being flexible enough for Elvis&rsquo;s dance moves.</p><p>Choice A is incorrect because "for this reason" illogically signals that the claim in this sentence is caused by the previous information about the material being flexible enough for Elvis&rsquo;s dance moves. Instead, the claim that the weight of the suit&rsquo;s rhinestones limited movement contrasts with the previous information about the jumpsuit&rsquo;s flexibility. Choice B is incorrect because "firstly" illogically signals that the claim in this sentence is the first in a series of claims about the jumpsuit being flexible enough for Elvis&rsquo;s dance moves. Instead, the claim that the weight of the suit&rsquo;s rhinestones limited movement contrasts with the previous information about the jumpsuit&rsquo;s flexibility. Choice D is incorrect because "in other words" illogically signals that the claim in this sentence is a paraphrase or restatement of the previous information about the material being flexible enough for Elvis&rsquo;s dance moves. Instead, the claim that the weight of the suit&rsquo;s rhinestones limited movement contrasts with the previous information about the jumpsuit&rsquo;s flexibility.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"420dea42","external_id":"29b663d7-ec23-47a6-9d1a-86a57df1e896","vaultid":null,"uId":"f631e689-a95c-4502-a35b-bc079d3f7054","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>A blend of gabardine and wool, the material for Elvis Presley&rsquo;s Gold Vine jumpsuit was flexible enough to allow the singer to perform his signature dance moves. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the added weight of the suit&rsquo;s swirling vines made of gold rhinestones likely limited Elvis&rsquo;s mobility to some degree.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"73b23dc4-cce6-4d00-809d-5bcea08f935a","content":"<p>For this reason,</p>"},{"id":"a74586c6-175b-4bfc-bfd7-765952d37c7b","content":"<p>Firstly,</p>"},{"id":"07f6bfac-5d5e-47c9-b4bb-649a59abe322","content":"<p>However,</p>"},{"id":"eb21f0ee-3a3c-40e3-b48a-20a0e9164d22","content":"<p>In other words,</p>"}],"keys":["07f6bfac-5d5e-47c9-b4bb-649a59abe322"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"However\" logically signals that the claim in this sentence&mdash;that the weight of the gold rhinestones likely limited Elvis&rsquo;s mobility&mdash;contrasts with the previous information about the material being flexible enough for Elvis&rsquo;s dance moves.</p><p>Choice A is incorrect because \"for this reason\" illogically signals that the claim in this sentence is caused by the previous information about the material being flexible enough for Elvis&rsquo;s dance moves. Instead, the claim that the weight of the suit&rsquo;s rhinestones limited movement contrasts with the previous information about the jumpsuit&rsquo;s flexibility. Choice B is incorrect because \"firstly\" illogically signals that the claim in this sentence is the first in a series of claims about the jumpsuit being flexible enough for Elvis&rsquo;s dance moves. Instead, the claim that the weight of the suit&rsquo;s rhinestones limited movement contrasts with the previous information about the jumpsuit&rsquo;s flexibility. Choice D is incorrect because \"in other words\" illogically signals that the claim in this sentence is a paraphrase or restatement of the previous information about the material being flexible enough for Elvis&rsquo;s dance moves. Instead, the claim that the weight of the suit&rsquo;s rhinestones limited movement contrasts with the previous information about the jumpsuit&rsquo;s flexibility.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061176,"updateDate":1755117061176}$SATQ$::jsonb, 1755117061176, 1755117061176),
    ($SATQ$4223d4a6$SATQ$, $SATQ$1fe4b8f4-dd17-42ca-a9b2-4a0c6d8c7e1e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>In 1965, Yale University historians claimed that a world map called the Vinland Map was drawn in the fifteenth century.</li>
<li>Since that time, the map&rsquo;s age has been the subject of debate.</li>
<li>In 2021, researchers conducted a study to analyze the elemental composition of the map&rsquo;s ink.</li>
<li>Their analysis revealed that the ink contains a titanium compound not used in inks until the 1920s.</li>
<li>The researchers concluded that the map was drawn in the twentieth century.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to present the study and its findings. Which choice most effectively uses relevant information from the notes to accomplish this goal?&nbsp;</p>$SATQ$, $SATQ$[{"id":"5767bf2c-4f45-4207-99b2-cb807bc9ce4b","content":"<p>Given the debate about the Vinland Map&rsquo;s age, researchers in 2021 conducted a study to analyze the elemental composition of the map&rsquo;s ink.</p>"},{"id":"dded8844-2aa4-4f4e-bcd9-284e8f5f53f1","content":"<p>A 2021 study of the Vinland Map&rsquo;s ink revealed that it contains a titanium compound not used in inks until the 1920s, indicating that the map was drawn in the twentieth century.</p>"},{"id":"1f80a1ba-fa8a-4a2d-ad56-87034d98c64d","content":"<p>The Vinland Map, believed by some to have been drawn in the fifteenth century, was the focus of a 2021 study.</p>"},{"id":"7d1181d1-03d7-443e-92d7-1251495a8a49","content":"<p>Aware that a certain titanium compound was not used in inks until the 1920s, researchers in 2021 studied the elemental composition of the Vinland Map&rsquo;s ink.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["dded8844-2aa4-4f4e-bcd9-284e8f5f53f1"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence effectively presents the study and its findings, providing relevant information: a 2021 study of the Vinland Map found that the map&rsquo;s ink contains a compound not used in inks until the twentieth century.</p><p>Choice A is incorrect. While the sentence introduces the study, it does not present the study&rsquo;s findings. Choice C is incorrect. While the sentence mentions the study, it does not effectively present the study or its findings. Choice D is incorrect. While the sentence introduces the study, it does not present the study&rsquo;s findings.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4223d4a6","external_id":"1fe4b8f4-dd17-42ca-a9b2-4a0c6d8c7e1e","vaultid":null,"uId":"8e9f0c43-8ece-4dc3-ad36-3e1aff021ac1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>In 1965, Yale University historians claimed that a world map called the Vinland Map was drawn in the fifteenth century.</li>\n<li>Since that time, the map&rsquo;s age has been the subject of debate.</li>\n<li>In 2021, researchers conducted a study to analyze the elemental composition of the map&rsquo;s ink.</li>\n<li>Their analysis revealed that the ink contains a titanium compound not used in inks until the 1920s.</li>\n<li>The researchers concluded that the map was drawn in the twentieth century.</li>\n</ul>","stem":"<p>The student wants to present the study and its findings. Which choice most effectively uses relevant information from the notes to accomplish this goal?&nbsp;</p>","answerOptions":[{"id":"5767bf2c-4f45-4207-99b2-cb807bc9ce4b","content":"<p>Given the debate about the Vinland Map&rsquo;s age, researchers in 2021 conducted a study to analyze the elemental composition of the map&rsquo;s ink.</p>"},{"id":"dded8844-2aa4-4f4e-bcd9-284e8f5f53f1","content":"<p>A 2021 study of the Vinland Map&rsquo;s ink revealed that it contains a titanium compound not used in inks until the 1920s, indicating that the map was drawn in the twentieth century.</p>"},{"id":"1f80a1ba-fa8a-4a2d-ad56-87034d98c64d","content":"<p>The Vinland Map, believed by some to have been drawn in the fifteenth century, was the focus of a 2021 study.</p>"},{"id":"7d1181d1-03d7-443e-92d7-1251495a8a49","content":"<p>Aware that a certain titanium compound was not used in inks until the 1920s, researchers in 2021 studied the elemental composition of the Vinland Map&rsquo;s ink.</p>"}],"keys":["dded8844-2aa4-4f4e-bcd9-284e8f5f53f1"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence effectively presents the study and its findings, providing relevant information: a 2021 study of the Vinland Map found that the map&rsquo;s ink contains a compound not used in inks until the twentieth century.</p><p>Choice A is incorrect. While the sentence introduces the study, it does not present the study&rsquo;s findings. Choice C is incorrect. While the sentence mentions the study, it does not effectively present the study or its findings. Choice D is incorrect. While the sentence introduces the study, it does not present the study&rsquo;s findings.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048)
